pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best Fit Penalty (Minimize residual space)
    // We favor bins that result in smaller residuals (tighter packing).
    // If the bin is new (post_residual == bin_capacity - item_size), add a significant penalty
    // to discourage opening new bins unless necessary.
    if bin_residual == bin_capacity {
        score += 45.0 + (progress * 20.0);
    }

    // 2. Lookahead Integration (Predictive Packing)
    // If we have a next item, check if it fits in the current post_residual.
    // If it fits perfectly or well, incentivize this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward placement that leaves room for the next item
            score -= (100.0 - post_residual as f64) * 0.5;
        } else {
            // Penalize placement if it blocks the next item from fitting here
            score += 15.0;
        }
    }

    // 3. Global State Balancing
    // If we have very few bins open, be more conservative.
    // If we have many bins open, be more aggressive in filling them.
    let density_factor = (open_bins_count as f64 / 10.0).min(5.0);
    score += (mean_residual - post_residual as f64) * density_factor;

    // 4. Critical Threshold Protection
    // If only one bin can fit the item, prioritize it to avoid fragmenting
    // the remaining open bins unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // 5. Fragmentation Penalty
    // Avoid creating "unusable" small gaps (e.g., < 10) if possible,
    // as they are unlikely to fit future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base penalty for creating small, unusable gaps (1-9 range is usually wasted)
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    }

    // 2. Lookahead mechanism: If the next item can fit perfectly or near-perfectly into the post_residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward placements that leave exactly enough room for the next item
            let diff = (post_residual - next_item_size) as f64;
            score -= (25.0 / (1.0 + diff));
        } else {
            // Penalize placements that block the next item from fitting here if it could have fit
            score += 15.0;
        }
    }

    // 3. Pressure management: If we are near the end of the stream, prioritize tight packing
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    // 4. Strategic new-bin thresholding
    // If bin_residual == bin_capacity, we are evaluating opening a new bin.
    // We only want to do this if current open bins are "too full" to accommodate future items efficiently.
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score = 0.0; // Must open first bin
        } else {
            // Only open a new bin if the mean residual is significantly smaller than the next item
            if mean_residual < next_item_size as f64 {
                score = 30.0; 
            } else {
                score = 100.0; // Strongly discourage opening new bin if existing ones have space
            }
        }
    } else {
        // 5. Prefer bins that keep the mean residual closer to the next_item_size
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.2;

        // 6. If this is the last chance for this item, prioritize it heavily
        if fitting_bins_count == 1 {
            score -= 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score: Favor smaller post_residual (Best Fit principle).
    let mut score = post;

    // Penalty for leaving a 'dead zone' that is too small for any likely future item.
    // We use the mean_residual as a dynamic threshold.
    if post > 0.0 && post < 10.0 {
        score += 25.0 * (1.0 - (post / 10.0));
    }

    // Lookahead logic: If the next item is large, prioritize bins that can accommodate it.
    // If current bin can't fit next item, penalize leaving a small residual.
    if next_item_size > 0 && post < next_item_size as f64 {
        score += (next_item_size as f64 - post) * 0.5;
    }

    // Dynamic thresholding based on stream progress:
    // Early in the stream, be conservative (fill bins tightly).
    // Late in the stream, allow slightly worse fits to consolidate remaining space.
    let consolidation_factor = (1.0 - progress) * 15.0;
    score += (post - mean_residual).abs() * consolidation_factor;

    // New bin logic:
    // If bin_residual == bin_capacity, we are evaluating opening a new bin.
    // Only open a new bin if the current best existing bin is extremely inefficient.
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score = 0.0;
        } else {
            // High penalty for opening a new bin unless existing bins are very full.
            score = 40.0 + (mean_residual * 0.5);
        }
    } else {
        // If this is the only bin that can fit the item, give it a massive priority boost.
        if fitting_bins_count == 1 {
            score -= 50.0;
        }
    }

    score
}

