pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit Penalty: Reward bins that are nearly full after placement.
    // We penalize larger post_residuals to encourage tight packing (Best Fit strategy).
    score += (post_residual as f64).powf(1.1);

    // 2. Lookahead Integration: If the next item fits into the current post_residual,
    // strongly incentivize this bin to reduce fragmentation.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 45.0 * (next_item_size as f64 / bin_capacity as f64);
    }

    // 3. New Bin Thresholding: Prevent opening new bins unless the current options
    // force a "bad" fit (creating a sliver of space that is hard to fill).
    if bin_residual == bin_capacity {
        // Base cost for opening a new bin.
        score = 65.0;
        // As we reach the end of the stream, opening a new bin is increasingly expensive.
        score += 40.0 * progress;
    } else {
        // 4. Global State Heuristic: If we have many open bins, penalize creating more
        // to encourage consolidating items into existing structures.
        score += (open_bins_count as f64).sqrt() * 5.0;

        // 5. Fragmentation Avoidance: If the post_residual is small (e.g., < 10),
        // it is often "dead space". Penalize this unless it's a perfect fit (0).
        if post_residual > 0 && post_residual < 10 {
            score += 25.0 * (1.0 - (post_residual as f64 / 10.0));
        }
    }

    // 6. Scarcity Constraint: If this is the last bin that can fit the item,
    // force its selection by lowering the score significantly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // The core objective is to minimize post_residual (Best Fit), 
    // but we apply non-linear penalties for creating "orphaned" residuals 
    // (space too small for common items) and modulate behavior based on progress.

    // Penalty for creating a bin with a residual that is likely to be unusable (e.g., < 10)
    // We penalize smaller post_residuals more heavily if they are in the "danger zone" (1..9).
    let orphan_penalty = if post < 10.0 && post > 0.0 {
        (10.0 - post) * 5.0
    } else {
        0.0
    };

    // Reward bins that align with the lookahead (next_item_size)
    // If post_residual can perfectly fit the next item, we prioritize this bin.
    let lookahead_reward = if next_item_size > 0 && post >= next_item_size as f64 {
        -(post - next_item_size as f64).exp() 
    } else {
        0.0
    };

    // Dynamic scaling: As the stream progresses, we become more conservative 
    // about opening new bins. If this is a new bin (bin_residual == bin_capacity),
    // we penalize it progressively more as we reach the end of the stream.
    let new_bin_penalty = if bin_residual == bin_capacity {
        50.0 * (1.0 + progress * 2.0)
    } else {
        0.0
    };

    // Coupling: interaction between current mean_residual and the fit quality.
    // If the bin is much tighter than the average, it's a good candidate.
    let efficiency_bias = (post - mean_residual) * 0.5;

    let score = post + orphan_penalty + lookahead_reward + new_bin_penalty + efficiency_bias;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" that is too small for future items.
    // If post_residual is small but > 0, it's often a waste unless it perfectly fits the next item.
    if post_residual > 0 && post_residual < 20 {
        score += 40.0;
    }

    // 2. Lookahead optimization: If next_item_size fits in the post_residual, reward this bin heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
    }

    // 3. Prevent opening a new bin if the item can fit into existing space.
    // If this is a new bin (bin_residual == bin_capacity) and we have fitting bins, penalize it.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 150.0;
    }

    // 4. Tight-fit preference: If post_residual is exactly 0, it's a perfect fill.
    if post_residual == 0 {
        score -= 20.0;
    }

    // 5. Global state normalization:
    // Avoid fragmenting bins if we are early in the stream; favor using existing bins
    // that are already below the mean residual to keep the distribution balanced.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // 6. Near-end-of-stream heuristic:
    // As we approach the end (step_index -> total_items), become more conservative about new bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && bin_residual == bin_capacity {
        score += 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Exact fit reward: Strong preference for closing bins perfectly.
    if post_residual == 0 {
        score -= 500.0;
    }

    // 2. Harmonic penalty: Penalize residuals that are too small to fit common item sizes (10-30).
    // If post_residual is in the "dead zone" (1..9), penalize it heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 150.0 / (post_residual as f64 + 1.0);
    }

    // 3. Lookahead integration: Favor bins that can accommodate the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 120.0; // High reward for "chaining"
        } else {
            // Penalize leaving a bin that cannot fit the next item if we have other options
            score += 40.0;
        }
    }

    // 4. Distributional balance: If the residual is much worse than the mean, penalize it.
    // This encourages filling bins evenly to keep residuals clustered.
    if (post_residual as f64) > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.5;
    }

    // 5. New bin threshold logic: 
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy cost based on open_bins_count.
    // We only open a new bin if the current options are truly terrible (high scores).
    if bin_residual == bin_capacity {
        // Base cost for opening a new bin is high to favor packing existing bins.
        score += 180.0;
        // Reduce cost if we have very few bins open to prevent fragmentation.
        score -= (open_bins_count as f64) * 5.0;
    }

    // 6. Fitting count pressure: If this is the only bin that fits the current item, 
    // significantly reduce its cost to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score: prioritize tighter fits (smaller post_residual).
    // Penalize large remainders non-linearly (quadratic growth) to avoid fragmentation.
    let mut score = post_res * post_res / 100.0;

    // Lookahead logic: if next_item_size is large, penalize small post_residual 
    // to keep space open for the upcoming item.
    if next_item_size > 0 {
        let next_f = next_item_size as f64;
        if post_res < next_f {
            score += (next_f - post_res) * 5.0;
        }
    }

    // Stream progression adjustment:
    // Early in the stream, favor filling existing bins (lower score).
    // Late in the stream, be more aggressive with new bins to avoid stranding items.
    let exhaustion_penalty = (progress * 20.0) * (open_bins_count as f64 / 10.0);
    score += exhaustion_penalty;

    // New bin penalty: 
    // If this is a new bin call (bin_residual == bin_capacity), apply a dynamic penalty.
    // We only open a new bin if the calculated score is lower than existing fits.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin is high, but decreases as we reach the end of the stream
        // or if the mean_residual of existing bins is already very low (fragmentation).
        let new_bin_base_cost = 45.0 - (progress * 15.0) - (mean_residual * 0.1);
        score = new_bin_base_cost;
    } else {
        // If it's an existing bin, favor bins that are already "tight" 
        // to keep the average residual low (Best Fit logic).
        score -= (bin_capacity as f64 - bin_residual as f64) * 0.05;
    }

    // Edge case: If this is the only bin that can fit the item, heavily incentivize it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score: prioritize smaller post_residual (Best Fit principle).
    // We apply a cubic penalty to large residuals to force tightness.
    let mut score = post.powi(3) * 0.001;

    // Lookahead logic: if the next item fits into the current post_residual,
    // we reward this bin significantly to encourage bin consolidation.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64).powi(2) * 0.5;
    }

    // Dynamic thresholding: as we progress through the stream, we become
    // more aggressive about filling bins tightly to avoid trailing waste.
    let tightness_penalty = (1.0 - progress) * post * 2.0;
    score += tightness_penalty;

    // Penalty for opening a new bin: if this is a new bin, we only pick it
    // if the current fitting options are extremely poor (high post_residual).
    if bin_residual == bin_capacity {
        // Only consider a new bin if the mean residual of existing bins is 
        // already quite high, indicating that existing bins are "fragmented".
        score += 250.0 - (mean_residual * 1.5);
    } else {
        // If this bin is the ONLY one that fits, give it a high priority (lower score).
        if fitting_bins_count == 1 {
            score -= 50.0;
        }
    }

    // Interaction term: penalize bins that deviate significantly from the mean
    // residual of open bins to keep the pack uniform.
    let deviation = (post - mean_residual).abs();
    score += deviation * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // Penalty for creating a bin that is "too empty" early on, but prioritize closing bins late in the stream
    if bin_residual == bin_capacity {
        // This is a new bin candidate. Penalize based on how much room is left in existing bins.
        score = 25.0 + (mean_residual * 0.5) + (progress * 15.0);
    } else {
        // If this is the only bin that fits the item, prioritize it heavily
        if fitting_bins_count == 1 {
            score -= 50.0;
        }

        // Lookahead heuristic: If the next item fits into the post-residual space, reward this placement
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 30.0;
            // Further reward if the post-residual becomes very small (perfect fit)
            score -= (100.0 - post_residual as f64) * 0.1;
        }

        // Penalty for leaving "fragmented" space that is too small for common items (below 10)
        if post_residual < 10 && post_residual > 0 {
            score += 40.0;
        }

        // Dynamic adjustment: As we approach the end of the stream, prioritize using existing bins
        // to avoid opening new ones unnecessarily.
        score += (progress * 20.0) * (open_bins_count as f64 / 10.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the remaining space (Best Fit principle).
    let mut score = post;

    // Penalty for creating "dead zones" (small residuals that cannot accommodate typical items).
    // If post_residual is between 1 and 9, it is highly likely to be wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (1.0 - (post / 10.0));
    }

    // Lookahead logic: if the next item is large, favor bins that leave enough space for it.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 30.0;
        } else {
            score -= 15.0 * (1.0 - (next_item_size as f64 / bin_capacity as f64));
        }
    }

    // Dynamic thresholding based on stream progress.
    // As we approach the end of the stream, we become more conservative about opening new bins.
    let new_bin_penalty = 25.0 + (progress * 40.0);

    // If bin_residual == bin_capacity, this is a "new bin" candidate.
    if bin_residual == bin_capacity {
        score = new_bin_penalty;
    }

    // If this is the only bin that fits the item, heavily prioritize it to avoid wasting a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Coupling with global state: penalize opening new bins if we have many underutilized bins.
    if bin_residual == bin_capacity && mean_residual > 30.0 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    if is_new_bin {
        // Penalty for opening a new bin: proportional to how much space we have left in existing bins
        // If we are near the end of the stream, we are more desperate to open new bins to avoid fragmentation
        score = 85.0 - (progress * 20.0) + (mean_residual * 0.5);
    } else {
        // Best Fit Decreasing logic: heavily reward small post_residual
        // Penalize bins that leave very small gaps (e.g., 1-4) which are hard to fill
