    let improvement = (bin_residual as f64 - mean_residual).abs() - (post_residual as f64 - mean_residual).abs();
    score -= improvement * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Initialize score with the primary objective: minimize post-fit residual (Best Fit).
    let mut score = post_residual as f64;

    // 1. Penalty for opening a new bin prematurely:
    // If this is a new bin (bin_residual == bin_capacity), penalize it unless the 
    // fitting_bins_count is zero (no other choice) or the current bin_residual is very tight.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if other bins can accommodate the item.
            score += 150.0 + (fitting_bins_count as f64 * 20.0);
        }
    }

    // 2. Lookahead matching:
    // If a next item exists, reward bins where the post_residual can accommodate the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // High reward for a bin that perfectly "prepares" for the next item.
            score -= 45.0;
            // Additional reward if the remaining space after both items is minimal.
            score -= (post_residual - next_item_size) as f64 * 0.5;
        }
    }

    // 3. Mean residual balancing:
    // Penalize bins that deviate significantly from the global mean residual to keep bins uniform.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    // 4. Progression scaling:
    // As we near the end of the stream, prioritize packing tighter (Best Fit) over 
    // lookahead to reduce the total count of bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    // 5. Critical thresholding:
    // If post_residual is very small (< 10), it's likely "dead space". 
    // Slightly penalize tiny residuals that cannot fit even the smallest items (1-10 range).
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    if is_new_bin {
        // Penalty for opening a new bin: scales with how many bins are already open 
        // and how close we are to the end of the stream.
        score = 15.0 + (open_bins_count as f64 * 2.5) + (progress * 10.0);
    } else {
        // Best Fit Decreasing logic: favor smaller post_residuals.
        // We penalize leaving small, unusable gaps (1-9) which are hard to fill.
        if post_residual > 0 && post_residual < 10 {
            score += 25.0;
        }

        // Lookahead heuristic: If the next item could fit into the current post_residual,
        // we heavily favor this bin.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0;
        }

        // Global state awareness: if we have many open bins, prioritize tighter packing
        // by penalizing bins that are significantly emptier than the global mean.
        if bin_residual > (mean_residual as u32 + 15) {
            score += 8.0;
        }

        // Criticality check: if this is the ONLY bin that can fit the item, 
        // prioritize it to avoid forced new bin creation.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the remaining space (Best Fit principle)
    let mut score = post_residual as f64;

    // Penalty for creating 'dead space' (leftover space < minimum possible item size 10)
    // We penalize tighter as we get closer to the end of the stream
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * (1.0 + progress * 2.0);
    }

    // Encourage filling bins that are already closer to the mean residual to keep bin levels uniform
    let residual_diff = (bin_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.5;

    // Lookahead: If we have a next item, penalize placements that make it impossible to fit
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 25.0 * (1.0 - progress);
        }
    }

    // If this is the only bin that can fit the item, prioritize it heavily
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 50.0;
    }

    // If considering a new bin, apply a dynamic threshold based on stream progress
    // We become more conservative (reluctant to open new bins) as the stream progresses
    if is_new_bin {
        score += 30.0 + (progress * 40.0);

        // If we have many open bins, penalize opening a new one
        score += open_bins_count as f64 * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating 'fragmentation': small residues that are unlikely to fit future items.
    // We target harmonic thresholds (e.g., 1/2, 1/3, 1/4 of capacity) as 'safe' zones.
    let r = post_residual as f64;
    let penalty_fragmentation = if r > 0.0 && r < 20.0 {
        100.0 / (r + 1.0)
    } else {
        0.0
    };

    // Reward placements that align with the next item size (lookahead synergy).
    // If next_item_size fits in the post_residual, we heavily reward this bin.
    let synergy = if next_item_size > 0 && next_item_size <= post_residual {
        -50.0 + (post_residual as f64 - next_item_size as f64) * 0.5
    } else {
        0.0
    };

    // Prefer bins that are already 'well-filled' (Best-Fit principle).
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    let fill_penalty = fill_ratio * 10.0;

    // If this is the only bin that fits the item (fitting_bins_count == 1), 
    // force a lower score to prevent opening a new bin unnecessarily.
    let urgency_bonus = if fitting_bins_count == 1 { -100.0 } else { 0.0 };

    // New bin logic: penalize opening a new bin unless the current mean_residual 
    // indicates that existing bins are too tight to accommodate future items.
    let new_bin_penalty = if bin_residual == bin_capacity {
        (open_bins_count as f64 * 5.0) + (mean_residual * 0.5)
    } else {
        0.0
    };

    score += penalty_fragmentation + synergy + fill_penalty + urgency_bonus + new_bin_penalty;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: If the post_residual is small (1-9), it is highly likely to be wasted.
    // We penalize values that leave a "sliver" that is too small for most items (assuming common item sizes > 10).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 0.1);
    }

    // 2. Lookahead Synergy: If the next item fits into the post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. Open Bin Pressure: Discourage opening a new bin unless existing bins are very full.
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty based on how many 
    // bins are already open and how much room remains in existing bins.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 5.0;
        score += (100.0 - mean_residual) * 0.5;
    } else {
        // Favor bins that are already open if they can fit the item
        score -= 10.0;
    }

    // 4. Scarcity/Bottlenecking: If this is the only bin that can fit the current item, 
    // prioritize it heavily to avoid unnecessary new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 5. Progression Scaling: As the stream nears completion, become more conservative about opening new bins.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
