    if is_new_bin {
        // Only consider a new bin if we have few fitting options or the current bins are nearly full.
        // Penalty is higher if we are early in the stream or if many bins are already open.
        score += 45.0 + (open_bins_count as f64 * 0.5) - (progress * 10.0);
