            score += 25.0;
        } else {
            // Reward keeping space for the next item.
            score -= 5.0;
        }
    }

    // 4. Global state pressure: If mean residual is high, we are being inefficient.
    // Force tighter packing by penalizing large post_residuals more heavily as we progress.
    score += (post_residual as f64 * progress * 0.5);

    // 5. Criticality: If this is the last fitting bin, prioritize it to avoid an unnecessary new bin.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 20.0;
    }

    // 6. Avoid "wasteland" bins: If post_residual is small but unusable (e.g. < 10), penalize.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
