    // 1. Penalty for creating "Dead Zones": If post_residual is smaller than the 
    // smallest possible item (assumed 10) but larger than 0, it's highly inefficient.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead Synergy: If the next item fits into the current post_residual, 
    // heavily reward this bin to encourage packing pairs.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 3. Harmonic Balancing: Favor residuals that are multiples of 25 (1/4 capacity) 
    // or 20 (1/5 capacity) to maintain flexible "buckets" for future items.
    if post_residual % 25 == 0 || post_residual % 20 == 0 {
        score -= 15.0;
    }

    // 4. Scarcity Management: If this is the only bin that can fit the item, 
    // prioritize it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // 5. New Bin Threshold: Discourage opening a new bin unless the residual 
    // pressure (mean_residual) is high, indicating current bins are becoming fragmented.
    if bin_residual == bin_capacity {
        // Only open a new bin if the average space in existing bins is tight
        if mean_residual > 20.0 {
            score -= 10.0;
        } else {
            score += 100.0;
        }
    }

    // 6. Global Progression: As the stream nears the end, prioritize tighter fits 
    // (lower residuals) to close out bins and minimize total count.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
