            // Towards the end of the stream, we are more aggressive about packing density.
            score += 25.0 + (progress * 20.0);
        }
    } else {
        // If the bin is already open, reward placements that keep the mean residual balanced.
        // This prevents creating one "very empty" bin and one "very full" bin.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.2;
    }

    // Critical threshold: If this is the last chance to fit an item (fitting_bins_count == 1),
    // and the post_residual is very small, prioritize it to avoid opening a new bin later.
    if fitting_bins_count == 1 && post_residual < 15 {
