pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // The core objective is to minimize post_residual (Best Fit), but we introduce
    // penalties for leaving "fragmented" space that is unlikely to fit future items.
    // A residual between 1 and 9 is often "dead space" (since min size is 10).
    let fragmentation_penalty = if post > 0.0 && post < 10.0 {
        15.0 * (1.0 - (post / 10.0))
    } else {
        0.0
    };

    // Use lookahead: if the next item is large and the current post_residual is too small,
    // penalize this bin to save space for the next item.
    let next_item_penalty = if next_item_size > post_residual && next_item_size > 0 {
        (next_item_size - post_residual) as f64 * 0.5
    } else {
        0.0
    };

    // Dynamic threshold: As the stream progresses, we become more conservative about
    // opening new bins. We bias towards filling existing bins more tightly.
    let progress_bias = progress * 20.0;

    // If this is a new bin (bin_residual == bin_capacity), we apply a significant 
    // baseline penalty to discourage opening new bins unless necessary.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        40.0 - progress_bias
    } else {
        0.0
    };

    // Combine terms:
    // 1. post: Best Fit principle
    // 2. fragmentation_penalty: Avoid creating unusable small gaps
    // 3. next_item_penalty: Lookahead heuristic
    // 4. new_bin_penalty: Discourage opening new bins early
    let score = post + fragmentation_penalty + next_item_penalty + new_bin_penalty;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
