pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the residual space remaining (Best Fit principle).
    // Penalize large residuals to prioritize tight packing.
    let mut score = post;

    // Non-linear coupling: As the stream progresses, prioritize closing bins 
    // that have very small residuals to avoid fragmentation.
    // We use a sigmoid-like pressure relative to the mean residual.
    let residual_deviation = (post - mean_residual).powi(2);
    score += residual_deviation * (1.0 - progress);

    // Lookahead penalty: If the next item is large, penalize bins that 
    // leave too little space for it (avoiding stranded fragments).
    if next_item_size > 0 {
        if post < next_item_size as f64 {
            score += (next_item_size as f64 - post) * 2.5;
        }
    }

    // New-bin logic: If this is an empty bin (bin_residual == bin_capacity),
    // impose a dynamic barrier. We only open a new bin if the average fit 
    // is poor or we are near the end of the stream.
    if bin_residual == bin_capacity {
        // Higher cost for opening new bins early in the stream.
        score += (bin_capacity as f64 * 0.7) * (1.0 - progress);

        // If many bins can already fit the item, penalize opening a new one heavily.
        if fitting_bins_count > 0 {
            score += fitting_bins_count as f64 * 15.0;
        }
    } else {
        // If this bin is the last one that can fit the item, 
        // reward this bin to prevent opening a new one unnecessarily.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    // Final smoothing: Penalize extreme residuals that are likely to stay empty.
    score += (post / bin_capacity as f64).powi(3) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
