    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // 1. Best-Fit Decreasing logic: penalize large post_residuals (wasted space)
    // We want post_residual to be as close to 0 as possible.
    score += post_residual as f64 * 0.5;

    // 2. Lookahead optimization: If next_item_size fits in the post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 1.2;
    }

    // 3. Penalty for opening new bins: Only open if the current fit is extremely poor.
    if is_new_bin {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if an existing bin could fit the item.
            score += 150.0 + (100.0 * (1.0 - progress));
        } else {
            // If no bins fit, this is mandatory.
            score -= 50.0;
        }
    }

    // 4. Global state adjustment: Favor bins that are already "tight" to keep others empty.
    // We penalize bins that have a residual significantly larger than the current mean.
    if !is_new_bin {
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score += deviation * 0.2;
    }

    // 5. Urgency factor: As we approach the end of the stream, prioritize closing bins.
    if progress > 0.8 {
        if post_residual < 10 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the residual space squared to heavily penalize large gaps (Best-Fit principle).
    let mut score = post_res * post_res;

    // Favor bins that, after placement, leave a residual close to the expected future item size
    // or leave a small enough gap to be filled by the lookahead item.
    if next_item_size > 0 {
        let diff = (post_res - next_item_size as f64).abs();
        score -= (100.0 - diff).powf(1.5);
    }

    // Dynamic penalty for opening new bins: 
    // As the stream progresses, we become more conservative about opening new bins.
    if bin_residual == bin_capacity {
        score += 2500.0 * (1.0 + progress);
    }

    // Adaptive pressure: If we have many open bins, penalize bins that increase the mean_residual
    // to encourage filling existing bins more compactly.
    if open_bins_count > 0 {
        score += (post_res - mean_residual) * (open_bins_count as f64).sqrt();
    }

    // Criticality check: If this is the only bin that can fit the item, 
    // significantly reduce its score to prevent opening a new bin prematurely.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5000.0;
    }

    // Non-linear coupling: penalize small, unusable residuals that are too small for 
    // common item sizes but too large to be considered "packed".
    if post_res > 0.0 && post_res < 10.0 {
        score += 1000.0 / post_res;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base penalty for creating small, unusable gaps (The "Fragment Trap")
    // If post_residual is < 10, it's likely dead space. Penalty increases as the gap gets smaller.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 1.0);
    }

    // 2. Lookahead logic: If the next item fits into the current post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 3. Fitting Bin pressure: If this is the only bin that fits the current item, 
    // force selection to avoid opening a new bin prematurely.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 100.0;
    }

    // 4. New bin management: If evaluating an empty bin, add a penalty based on 
    // the current density to discourage opening new bins when space is available.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64 * 15.0) + (mean_residual * 0.5);
    }

    // 5. Harmonic refinement: Use modulo arithmetic to favor "clean" fits (multiples of 20).
    // This tends to group items that pack well together (e.g., 20+20+20+20+20 = 100).
    let rem = post_residual % 20;
    if rem == 0 {
        score -= 10.0;
    } else if rem > 15 {
        score += 5.0;
    }

    // 6. Progressive scaling: As the stream nears completion, become more conservative about 
    // opening new bins.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Strict Dead Space Avoidance: Penalize post_residual values that create unusable gaps.
    // Gaps < 10 are almost always unusable given the item size range (10-100).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. Open Bins Pressure: Penalize opening new bins when capacity is available,
    // but allow it if existing bins are poor fits.
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin is proportional to the ability to fit the item elsewhere.
        score += (fitting_bins_count as f64) * 20.0;
        // Further penalize opening a new bin if we are early in the stream to save bins for later.
        score += 15.0 * (1.0 - (step_index as f64 / total_items as f64));
    }

    // 3. Lookahead Logic: If the next item exists, favor bins that can accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0; // Reward bins that can fit the next item.
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 5.0; // Penalize bins that would "block" the next item.
        }
    }

    // 4. Global Efficiency: If the post_residual is exactly 0, it is a perfect fit.
    if post_residual == 0 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize opening new bins unless necessary (fitting_bins_count is 0)
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 500.0; // Strong penalty for opening new bin if space exists
        } else {
            score -= 50.0; // Slight incentive to open if no space available
        }
    }

    // 2. Aggressive 2-step lookahead matching
    // If the next item fits perfectly into the post_residual, prioritize this bin
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // Perfect fit for next item
        } else if post_residual > next_item_size {
            // Penalize leaving a gap that is slightly too small for the next item
            // but keep it attractive if it's large enough to accommodate it
            score += (post_residual as f64 - next_item_size as f64) * 0.5;
        } else {
            // Gap is too small for next item, penalize proportionally to the wasted space
            score += (next_item_size - post_residual) as f64 * 2.0;
        }
    }

    // 3. Balance against global state
    // Avoid creating bins that deviate significantly from the mean residual
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    // 4. Prefer bins that are nearly full (Best Fit principle)
    // post_residual 0 is ideal, so we don't penalize it. 
    // Larger post_residual is penalized to encourage tight packing.
    score += (post_residual as f64) * 0.8;

    // 5. Progression awareness
    // Be more conservative with bin usage as we reach the end of the stream
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score += (post_residual as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Penalize creating "dead space" (residuals too small to fit common items)
    // Residuals in the range [1, 9] are highly problematic.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead: If the next item fits into the post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 * (1.0 - progress);
    }

    // 3. Dynamic Thresholding: As we approach the end of the stream, prioritize 
    // filling existing bins over opening new ones.
    if fitting_bins_count > 0 && bin_residual != bin_capacity {
        // Reward placements that keep the bin residual closer to the global mean.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.5;
    } else if bin_residual == bin_capacity {
        // Penalty for opening a new bin: increases with progress to force consolidation.
        score += 30.0 + (progress * 40.0);
    }

    // 4. Compactness bias: Penalize bins that are becoming too empty relative to the mean.
    if post_residual > (mean_residual as u32) {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score: prioritize tighter fits (Best Fit principle)
    let mut score = post_res;

    // Penalty for creating "dead space": if post_residual is small but > 0, 
    // it's often better to have used a different bin or opened a new one.
    // We penalize small residues that are too small to fit common items (e.g., < 15).
    if post_res > 0.0 && post_res < 15.0 {
        score += (15.0 - post_res) * 2.0;
    }

    // Lookahead logic: if the next item is large, avoid bins that leave very little space
    // that won't accommodate the next_item_size.
    if next_item_size > 0 {
        if post_res < next_item_size as f64 {
            score += (next_item_size as f64 - post_res) * 1.5;
        }
    }

    // Interaction with stream progress: as we near the end of the stream, 
    // we become more conservative about opening new bins.
    // If this is a new bin (bin_residual == bin_capacity), penalize it 
    // more heavily as progress increases to force consolidation.
    if bin_residual == bin_capacity {
        score += 20.0 + (progress * 40.0);
    }

    // Reward bins that keep the mean residual balanced.
    // Bins that move the residual closer to the global mean are favored.
    let residual_deviation = (post_res - mean_residual).abs();
    score += residual_deviation * 0.5;

    // Favor bins that are "almost full" if they fit the item, 
    // but only if we are not at the very start of the stream.
    if progress > 0.1 && post_res < 10.0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Penalize residuals that are small but not zero (fragmentation).
    // If post_residual is in (0, 10), it's likely "dead space" for future items.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    }

    // 2. Lookahead Logic: If the next item fits into the current post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
    }

    // 3. Last Chance Heuristic: If this is the only bin that fits the item, make it highly attractive.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // 4. Capacity Efficiency: Favor filling bins to near-capacity (harmonic alignment).
    // If post_residual is 0, this is a perfect fit.
    if post_residual == 0 {
        score -= 20.0;
    }

    // 5. Global Density: If we have many open bins, penalize opening a new one (bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        // High penalty for new bin if we have many bins already open
        score += (open_bins_count as f64) * 5.0;

        // If we are late in the stream, be more conservative about opening new bins.
        let progress = step_index as f64 / total_items as f64;
        score += progress * 20.0;
    }

    // 6. Mean Residual Coupling: Avoid opening bins that deviate significantly from the mean state.
    if bin_residual != bin_capacity {
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

