    // 3. Pressure: Penalize opening new bins, but favor tight fits in existing ones.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // High penalty for opening a new bin unless existing bins are very full.
        score += 30.0 + (open_bins_count as f64 * 2.0);
    } else {
        // Reward filling existing bins to keep open_bins_count low.
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    }

    // 4. Criticality: If this is the only bin that fits the item, make it highly attractive.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    // 5. Progression: As the stream nears the end, prioritize closing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if is_new_bin {
