    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // If bin is empty, assign a baseline cost.
    // We penalize opening a new bin by setting its base score relatively high,
    // making it only attractive if existing bins lead to very poor fits.
    let is_new_bin = bin_residual == bin_capacity;
    let mut score = if is_new_bin { 45.0 } else { post_residual as f64 };

    // 1. Reward Best-Fit behavior: Lower post_residual is generally better.
    // 2. Penalty for creating "dead zones": if post_residual is between 1 and 9,
    //    it is unlikely to fit any future item, so penalize heavily.
    if !is_new_bin && post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 3. Lookahead Matching: If the next item fits perfectly into the post_residual,
    //    heavily reward this bin to clear it out.
    if next_item_size > 0 && next_item_size <= post_residual {
        let diff = (post_residual - next_item_size) as f64;
        // Reward small gaps (prefer exact matches)
        score -= (25.0 - diff).max(0.0);
    }

    // 4. Distribution Balancing: If the bin is much emptier than the mean,
    //    penalize it to favor packing into already-full bins.
    if !is_new_bin && (bin_residual as f64) > (mean_residual * 1.2) {
        score += 15.0;
    }

    // 5. Urgency: If this is the only bin that can fit the item, 
    //    drastically reduce the score to ensure it is picked over opening a new one.
    if fitting_bins_count == 1 && !is_new_bin {
