    }

    // 3. Fragmentation Control:
    // Penalize creating small unusable gaps (e.g., < 10) unless it's a perfect fit.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0 * (1.0 - progress);
    }

    // 4. Global State Awareness:
    // If mean_residual is low, we are in a tight packing scenario. 
    // Reward bins that keep the residual close to the current mean to maintain uniformity.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    // 5. New Bin Thresholding:
    // If this is a new bin (bin_residual == bin_capacity):
    // Only open a new bin if we have many open bins already (high open_bins_count) 
    // or if the current packing is inefficient.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin
        score += 45.0; 
        // If we have many open bins, penalize more to force reuse
        score += (open_bins_count as f64) * 2.0;
        // As we approach the end of the stream, prioritize closing bins
        score += (1.0 - progress) * 10.0;
    }

    // 6. Last Chance Logic:
    // If this is the only bin that can fit the item, favor it heavily to avoid unnecessary new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
