    // Penalty for leaving space that is too small for common items (e.g., < 20)
    if post_residual > 0 && post_residual < 20 {
        score += 40.0 * (1.0 - (post_residual as f64 / 20.0));
    }

    // Harmonic alignment: Reward post_residuals that are close to multiples of 25 (100/4)
    let remainder = post_residual % 25;
    score += (remainder as f64).min((25 - remainder) as f64) * 0.5;

    // Lookahead logic: If the next item fits into the current post_residual, drastically reduce score.
    if next_item_size > 0 && next_item_size <= post_residual {
