    // 3. Global Efficiency: If this bin is the only one that fits, keep it.
    // Otherwise, prefer bins that keep the mean_residual high (to allow larger items).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
