    // 4. New Bin Thresholding: 
    // Heavily penalize opening a new bin unless the current mean_residual 
    // is too low to accommodate upcoming expected sizes.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && mean_residual > (item_size as f64 * 1.2) {
