pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Strict Dead Space Avoidance: Penalize residuals that are too small to fit common items
    // If post_residual is in the range (0, 10), it is highly likely to become unusable "dead space".
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64);
    }

    // 2. Lookahead Integration: If the next item fits into the current post_residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 3. Global Bin Pressure: If we have many open bins, penalize opening a new one or using a bin
    // that increases the count of high-residual bins.
    let progress = step_index as f64 / total_items as f64;
    let open_penalty = (open_bins_count as f64) * (1.0 + progress);
    score += open_penalty;

    // 4. New Bin Candidate Handling: If this is an empty bin (bin_residual == bin_capacity),
    // only choose it if the penalty of forcing a bad fit in existing bins is higher.
    if bin_residual == bin_capacity {
        // High base cost for opening a new bin, modified by how many bins are already open.
        score = 65.0 + (open_bins_count as f64 * 2.0);
    }

    // 5. Fitting constraint: If this is the only bin that can fit the item, prioritize it heavily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // 6. Balance against mean_residual: Prefer bins that keep the bin closer to the global mean.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Encourage Best Fit (minimize post_residual).
    // The base score is already post_residual, which favors tight packing.

    // 2. Lookahead Aggression: If next_item fits perfectly in the current post_residual,
    // prioritize this bin to prevent fragmentation.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        // Reward small gaps that accommodate the next item perfectly (gap == 0)
        score -= (100.0 - (gap as f64 * 2.0));
    }

    // 3. Penalize New Bin Creation: Unless the current fit is terrible (post_residual > 40),
    // heavily penalize opening a new bin.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        if post_residual > 40 {
            score -= 20.0;
        } else {
            score += 150.0;
        }
    }

    // 4. Distribution Balancing: If the bin's residual is significantly better than the mean,
    // prioritize it to keep the "fill level" uniform across bins.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // 5. Last Chance Logic: If this is the only bin that can fit the item,
    // lower the score to ensure it is picked over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 6. Progress Scaling: As the stream nears completion, become more aggressive
    // about filling gaps (lower score for tighter fits).
    let progress = step_index as f64 / total_items as f64;
    score += (progress * 10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
    // Logic:
    // 1. Prioritize Best-Fit (minimizing post_residual).
    // 2. Penalize opening new bins unless the fit is extremely poor in existing bins.
    // 3. Incorporate lookahead: if next_item_size is large, favor bins that can accommodate it.

    let mut score = post_residual as f64;

    // Is this a new bin?
    let is_new_bin = bin_residual == bin_capacity;

    if is_new_bin {
        // Only open a new bin if the current fit quality across all bins is very poor.
        // We penalize the new bin by the mean residual of existing bins.
        score += mean_residual * 0.8;

        // If there are bins that could fit the item, heavily penalize opening a new one
        // unless the item is very large (likely to cause fragmentation elsewhere).
        if fitting_bins_count > 0 {
            score += (item_size as f64 * 1.5) + (open_bins_count as f64 * 2.0);
        }
    } else {
        // If it's an existing bin, check lookahead compatibility.
        // If next_item_size exists, penalize bins that would leave too little room for it.
        if next_item_size > 0 && post_residual < next_item_size {
            // Penalty for stranding the next item
            score += (next_item_size - post_residual) as f64 * 0.5;
        }

        // Favor bins that become "tight" (post_residual near 0)
        // penalizing large gaps that are hard to fill later.
        score += (post_residual as f64).powf(1.2) * 0.1;
    }

    // Dynamic time horizon adjustment: 
    // As the stream progresses, prioritize closing bins (minimizing open_bins_count).
    let progress = step_index as f64 / total_items as f64;
    score += (open_bins_count as f64) * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the remaining space (Best Fit principle)
    let mut score = post_residual as f64;

    // Penalty for creating a "dead zone" (residual too small to fit typical future items)
    // We target a residual that minimizes unusable fragments.
    if !is_new_bin {
        let fragment_penalty = (10.0 - post_residual as f64).exp();
        score += fragment_penalty;
    }

    // Lookahead coupling: If the next item is large, favor bins that can accommodate it.
    if next_item_size > 0 && !is_new_bin {
        if post_residual < next_item_size {
            score += 25.0 * (1.0 - progress);
        }
    }

    // Dynamic thresholding for opening new bins:
    // As the stream progresses, become more conservative about opening new bins.
    if is_new_bin {
        if fitting_bins_count > 0 {
            // Apply non-linear resistance to opening a new bin if others exist.
            score += 40.0 + (progress * 60.0);
        } else {
            // If no other bin fits, this is the baseline cost of progress.
            score = 0.0;
        }
    }

    // Adjust for bin density: prefer bins closer to the mean residual to keep bins balanced.
    let density_diff = (post_residual as f64 - mean_residual).abs();
    score += density_diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

