        // Reward configurations where the remaining space after next_item fits a harmonic divisor
        let remaining_after_next = post_residual - next_item_size;
        if remaining_after_next == 0 {
            score -= 50.0; // Perfect packing for two items
        } else if bin_capacity % (remaining_after_next + 1) == 0 {
            score -= 10.0;
        }
    }

    // 3. New Bin Thresholding:
    // If this is a new bin (bin_residual == bin_capacity), penalize it 
    // unless fitting_bins_count is very low, suggesting we are struggling to pack.
    if bin_residual == bin_capacity {
        score += 45.0; 
        // If we have few options, reduce the penalty for opening a new bin
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
    }

    // 4. Global State Balancing:
    // Avoid creating bins that deviate significantly from the mean residual of current bins.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.5;

    // 5. Progression Scaling:
    // As we approach the end of the stream, prioritize closing bins (tight packing).
    let progress = step_index as f64 / total_items as f64;
    score += progress * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
