    // If post_residual is < 10 and > 0, it is highly likely to be wasted space.

    let mut score = post_residual as f64;

    // 1. Penalize small, unusable gaps (1..9) as they are likely to remain empty.
    if post_residual > 0 && post_residual < 10 {
