    if open_bins_count > 5 {
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    }

    // 4. If this is a new bin (bin_residual == bin_capacity), penalize opening it
    // unless it's the only option or the existing bins are very inefficient.
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin, scaled by current bin density.
        score += 60.0 + (mean_residual * 0.5);
    }

    // 5. If this is the last chance for the item (fitting_bins_count == 1), 
    // significantly reduce the score to ensure we don't force a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
