    // We target residuals that are either 0 (perfect fit) or >= next_item_size.
    if post_residual > 0 && post_residual < next_item_size {
        score += 50.0 + (next_item_size - post_residual) as f64;
    }

    // Harmonic bias: If we have multiple bins, prioritize filling bins that are already "tight"
    // to keep the number of active bins low.
    if bin_residual < bin_capacity {
        score -= (bin_capacity - bin_residual) as f64 * 0.5;
