    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 20.0;
        }
    }

    // Progress normalization: As the stream nears the end, become more aggressive about 
    // packing tightly to avoid stragglers.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

