    // We prioritize keeping the residual low (Best Fit logic) but adjust for future needs.
    let mut score = post + fragmentation_penalty + lookahead_penalty + deviation_penalty + new_bin_bias;

    // If this is the last chance to fit into an existing bin (fitting_bins_count == 1), 
    // significantly lower the score to force acceptance and avoid an unnecessary new bin.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post-residuals to favor tight packing
    // We aim for post_residual == 0 (perfect fit).
    score += post_residual as f64 * 1.5;

    // 2. Harmonic Lookahead: If next_item_size is known, favor bins that accommodate it.
    // If post_residual is smaller than next_item_size, it's a "dead" space trap.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 2.5;
        } else {
            // Reward bins that can accommodate the next item comfortably
            score -= (post_residual - next_item_size) as f64 * 0.8;
        }
    }

    // 3. New Bin Thresholding: Discourage opening a new bin unless the fit is truly optimal.
    if bin_residual == bin_capacity {
        // Only open a new bin if the mean residual is already quite low (bins are full).
        // Otherwise, prioritize existing bins to keep open_bins_count low.
        score += mean_residual * 0.5;
        if fitting_bins_count > 0 {
            score += 40.0; // Heavy penalty for opening new bin if space exists
        }
    }

    // 4. Harmonic Fragmentation Control:
    // If we have very few fitting bins, we are forced to be less picky about the residual.
    if fitting_bins_count == 1 {
        score -= 20.0; // Aggressively take the last chance fit
    }

    // 5. Progression Weighting:
    // As we approach the end of the stream, tighten the constraints (lower residuals become more critical).
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

