    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. Lookahead optimization: If the next item cannot fit in the current post_residual,
    // but could have fit if we chose a different bin, penalize this choice.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0;
