        // 4. Tightness reward: Favor bins where the post_residual is minimized.
        // This naturally implements a Best-Fit behavior.
        score -= (100.0 - post_residual as f64) * 0.1;
    }

    // 5. Global state normalization: As we approach the end of the stream, 
    // prioritize closing open bins over starting new ones.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && bin_residual == bin_capacity {
        score += 100.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base penalty for opening a new bin
    if bin_residual == bin_capacity {
        score += 45.0;
    }

    // 2. Best-Fit logic: penalize large post_residuals (wasted space)
    // but normalize against the mean_residual to avoid fragmentation
    score += (post_residual as f64 - mean_residual).powi(2) * 0.1;

    // 3. Lookahead Matching (The "Tightness" Incentive)
    // If we can fit the next item perfectly in this bin, prioritize this bin heavily.
    if next_item_size > 0 {
