        } else if post_residual > next_item_size {
            // Reward bins that leave exactly enough room for the next item
            score += (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // Penalty for stranding the next item
            score += 15.0;
        }
    }

    // 4. Scarcity management: if only one bin can fit the item, 
    // we are forced to use it; lower the score to ensure it is picked.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // 5. Progress-based scaling: become more aggressive as we approach the end of the stream
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
    // Heuristic Strategy: Best-Fit Decreasing variant with dynamic lookahead penalty.

    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items as f64;

    // Base score: Favor smaller post-residuals (Best-Fit logic).
    let mut score = post_residual as f64;

    // Penalty for creating a new bin:
    // Only open a new bin if the current item is very large or if we are late in the stream
    // and the current bin fit is extremely poor (large residual).
    if is_new_bin {
        if fitting_bins_count == 0 {
            // Must open a new bin, neutralize the penalty.
            score = 10.0;
        } else {
            // Heavily penalize opening a new bin if other bins exist.
            // Penalty scales with the average efficiency of existing bins.
            score = 150.0 + (mean_residual * 0.5) + (progress * 50.0);
        }
    } else {
        // Within an existing bin:
        // 1. Reward fits that leave very little space (Best Fit).
        // 2. Penalize fits that leave 'dead zones' (e.g., residual 1-9) where future items are unlikely to fit.
        if post_residual > 0 && post_residual < 10 {
            score += 25.0;
        }

        // 3. Lookahead coupling: If the next item is large, prioritize keeping space for it.
        if next_item_size > 0 {
            if post_residual < next_item_size {
                // This placement makes the next item impossible to fit here.
                score += 30.0 * (1.0 - progress);
            } else {
                // This placement preserves space for the next item.
                score -= 10.0 * (1.0 - progress);
            }
        }

        // 4. Global state coupling: If we have many open bins, penalize 'loose' fits.
        if open_bins_count > 5 {
            score += (post_residual as f64) * 0.2;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

