    let mut score = post_res;

    // Penalty for leaving "dead space": small residuals that are unlikely to fit future items.
    // We define "dead" as < 10 (since min item size is likely around 10).
    if post_res > 0.0 && post_res < 10.0 {
        score += 50.0 * (1.0 - progress);
    }

    // Lookahead logic: if the next item is large, avoid leaving a residual that is too small for it.
    if next_item_size > 0 {
        if post_res < next_item_size as f64 {
