        score += 40.0 + (60.0 * progress);
    }

    // Heuristic coupling: Reward bins that keep the mean residual balanced,
    // preventing the creation of extreme outliers.
    let residual_diff = (post_res - mean_residual).abs();
    score += 0.5 * residual_diff;

    // Favor fitting in a bin if it's the only one that can fit the item
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
