pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // The core objective is to minimize post_residual (Best Fit), but we introduce
    // non-linear penalties for leaving "bad" fragments that are hard to fill.
    // A residual of 1..9 is often a "dead zone" because items are >= 10.
    let dead_zone_penalty = if post_residual < 10 && post_residual > 0 { 45.0 } else { 0.0 };

    // Lookahead logic: if next_item_size is large, we want to prioritize bins 
    // that can accommodate it. If we can't fit the next item, we penalize the bin.
    let lookahead_penalty = if next_item_size > 0 && post_residual < next_item_size {
        (next_item_size - post_residual) as f64 * 0.5
    } else {
