    };

    // Progress-based scaling: As the stream nears the end, we become more aggressive 
    // about using existing bins to avoid opening new ones (penalize new bin creation).
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        30.0 + (progress * 50.0) 
    } else {
        0.0
    };

    // Interaction between mean_residual and the current bin to encourage packing
    // tightly relative to the average state of the system.
    let relative_tightness = (post - mean_residual).powf(1.2);

    let mut score = post + dead_zone_penalty + lookahead_penalty + new_bin_penalty + relative_tightness;

    // Favor bins where fitting_bins_count is low to preserve "flexible" bins for later.
    if fitting_bins_count > 1 && !is_new_bin {
        score += 5.0 * (fitting_bins_count as f64).ln();
    }

    score
}

