    let mut score = post;

    // Penalty for creating small, unusable gaps ("fragmentation").
    // Gaps between 1 and 9 are highly undesirable.
    if post > 0.0 && post < 10.0 {
        score += 50.0 * (1.0 - (post / 10.0));
    }

    // Lookahead logic: If we have a next item, favor bins that can accommodate it.
    if next_item_size > 0 {
        if post >= next_item_size as f64 {
            score -= 15.0 * (1.0 - progress);
        } else {
            score += 10.0 * progress;
        }
    }

    // Strategic behavior for open bins vs new bin:
    // If this is a new bin (bin_residual == bin_capacity), penalize based on 
    // the count of currently available fitting bins to force Best Fit.
    if bin_residual == bin_capacity {
        // As the stream progresses, become more conservative about opening new bins.
        score += 40.0 + (fitting_bins_count as f64 * 20.0 * (1.0 - progress));
    } else {
        // Reward bins that keep the mean residual balanced, preventing extreme variance.
        let deviation = (post - mean_residual).abs();
        score += deviation * 0.5;
    }

    // Final scaling: favor bins that are nearly full towards the end of the stream
    // to consolidate space.
    score -= (bin_capacity as f64 - post) * 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating a "dead zone" (small residuals that likely won't fit future items)
    // 0-9 is almost useless, 10-19 is very difficult.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 20.0;
    }

    // Lookahead logic: if next_item_size is large, favor larger post_residuals to accommodate it.
    // If next_item_size is small, prioritize tight packing (Best Fit).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalty for stranding the next item
            score += (next_item_size - post_residual) as f64 * 1.5;
        } else {
            // Reward for keeping space for the next item
            score -= (post_residual - next_item_size) as f64 * 0.5;
        }
    }

    // Harmonic preference: Favor bins that align with common item size clusters
    // By penalizing residuals that are not multiples of 20 (frequent bin-filling steps)
    if post_residual % 20 != 0 {
        score += 5.0;
    }

    // Handle new bin opening logic
    if bin_residual == bin_capacity {
        // Only open a new bin if the current packing is very inefficient
        // or if we are forced to (only one bin fits and it's a poor fit)
        if fitting_bins_count > 0 {
            score += 40.0; 
        } else {
            score -= 10.0;
        }
    }

    // Global state awareness: If we have many bins open, be more aggressive with packing
    score += (open_bins_count as f64) * 0.1;

    // Progress awareness: Tighten packing towards the end of the stream
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

