        score += 50.0;
    }

    // 2. Lookahead Synergy: If post_residual perfectly matches or leaves space for the next item, reward it.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // Perfect fit for next
        } else if post_residual > next_item_size {
            // Reward bins that can accommodate the next item while minimizing waste
            score -= 20.0 * (next_item_size as f64 / (post_residual as f64 + 1.0));
        }
    }

    // 3. Global Bin Management:
    // If we have many open bins, discourage opening a new one unless it's a perfect fit.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        if open_bins_count > 0 {
            // Penalty for opening a new bin when existing ones exist
            score += 45.0;
        }
        // If it's a new bin, we want to prioritize it only if it's a "clean" start
        score += (item_size as f64) * 0.1;
    } else {
        // Favor bins that are closer to the mean residual to keep bin levels balanced
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.2;
    }

    // 4. Scarcity handling:
    // If this is the only bin that fits, prioritize it heavily to avoid unnecessary new bins
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
    // Archetype: "Lookahead-Aware Best-Fit Decreasing with Dynamic Penalty"

    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. If this is a new bin, penalize based on the current global state to discourage 
    // opening bins too early unless the fit quality is truly poor elsewhere.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin is scaled by the number of open bins.
        // As the stream progresses, we become more conservative about opening new bins.
        score = 25.0 + (open_bins_count as f64 * 0.5) + (progress * 10.0);
    } else {
        // 2. Best-Fit logic: Smallest post_residual is generally best (lower score).
        // Penalize bins that leave very small "sliver" residuals (e.g., 1-4)
        // that are unlikely to be filled by future items (10-100).
        if post_residual > 0 && post_residual < 10 {
            score += 15.0;
        }

        // 3. Lookahead integration: 
        // If the next item fits into the post_residual, prioritize this bin (subtract score).
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }

        // 4. Global state coupling:
        // If the current bin's residual is significantly lower than the global mean,
        // it is a "tight" bin. Prefer filling tight bins to keep them from becoming 
        // permanent blockers of space.
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }

        // 5. Criticality adjustment:
        // If this is the only bin that can fit the item, we are forced to pick it.
        // Lowering the score ensures we don't accidentally prefer a new bin.
        if fitting_bins_count == 1 {
            score -= 50.0;
        }
    }

    score
