        score += (open_bins_count as f64) * 5.0;

        // If the item can fit into existing bins, heavily penalize opening a new one.
        if fitting_bins_count > 0 {
            score += 45.0;
        }
    }

    // 3. Lookahead Integration: If the next item is large, prioritize keeping space open.
    // If next_item_size is large (e.g., > 60), we want to preserve bins with higher residuals.
    if next_item_size > 60 {
        if post_residual < next_item_size {
            score += 15.0;
        }
    }

    // 4. Mean Residual Balancing: Prefer bins closer to the global mean to maintain uniformity
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    // 5. Progression Scaling: As the stream nears the end, be more aggressive at filling bins.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

