            score -= (next_item_size as f64) * 0.8;
        } else {
            // Penalize if the next item is blocked from this bin
            score += (next_item_size as f64) * 0.5;
        }
    }

    // 3. Global State: Dynamically discourage new bins as the stream nears completion
    // If bin_residual == bin_capacity, we are evaluating a new bin.
    if bin_residual == bin_capacity {
        // High penalty for opening new bins if we are deep in the stream
        score += (1.0 - progress) * 40.0;
        // Also penalize new bins if many open bins still have room
        score += (open_bins_count as f64) * 5.0;
    } else {
        // Encourage using existing bins that are already "half-full" to keep others empty
        score -= (bin_capacity - bin_residual) as f64 * 0.2;
    }

    // 4. Scarcity handling: If this is the only bin that fits the item, prioritize it strongly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 5. Balance residuals: Avoid creating bins with extremely low residuals if mean_residual is high
    if post_residual < 5 && mean_residual > 20.0 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // The core objective is to minimize post_residual (Best Fit), 
    // but we apply non-linear penalties to prevent fragmentation.

    // 1. Base score: Favor smaller post_residual (tighter fit).
    let mut score = post;

    // 2. Fragment penalty: Penalize very small, unusable residuals (1-9) 
    // especially as the stream progresses, to encourage creating space for future items.
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * (1.0 + progress * 2.0);
    }

    // 3. Lookahead coupling: If next_item_size is large, penalize bins that 
    // would result in a residual just slightly too small to hold the next item.
    if next_item_size > 0 {
        let diff = post - (next_item_size as f64);
        if diff < 0.0 && diff > -15.0 {
            score += 25.0 * (1.0 - progress);
        }
    }

    // 4. Open-bin consolidation: Penalize opening a new bin if we have many 
    // open bins already, unless the fit is perfect (post == 0).
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 15.0 * (1.0 + progress) * (open_bins_count as f64).sqrt();
    }

    // 5. Global efficiency: If the current bin's post_residual is significantly 
    // worse than the mean, penalize it relative to the stream progression.
    let dev = post - mean_residual;
    if dev > 0.0 {
        score += dev * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
