        // bin utilization is predicted to be poor compared to the mean.
        score += 45.0 + (open_bins_count as f64 * 0.5);
    }

    // Lookahead logic: if next_item_size is known, penalize bins that cannot fit it.
    if next_item_size > 0 && !is_new_bin {
        if post_residual < next_item_size {
            score += 15.0;
        }
    }

    // Pressure to consolidate: if we have many bins open, penalize the creation of new ones
    // and prefer bins that are already partially filled.
    if open_bins_count > 5 {
        score += (open_bins_count as f64) * 0.2;
    }

    // Favor bins that are closer to the mean residual to keep bin fill-levels balanced
    let residual_diff = (bin_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

