    // 4. New bin threshold:
    // If bin_residual == bin_capacity, this is the cost to open a new bin.
    // Scale this cost by the number of open bins to discourage fragmentation.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 5.0;
    }

    // 5. Balance with mean_residual:
    // Prefer bins that stay close to the average density to keep future flexibility.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.5;

