    let post_res = post_residual as f64;

    // Base score: prioritize tighter fits (Best Fit principle).
    // We penalize larger post_residuals quadratically to avoid fragmentation.
    let mut score = post_res.powi(2);

    // Penalty for creating a "small" residual that is unlikely to fit future items.
    // If post_res is small (e.g., < 10), it's often "dead space".
    if post_res > 0.0 && post_res < 15.0 {
        score += (15.0 - post_res).powi(2) * 2.0;
    }

    // Interaction with mean_residual: If this bin is already emptier than average, 
    // placing an item here is more efficient than opening a new bin or using a tight bin.
    if (bin_residual as f64) > mean_residual {
        score -= (bin_residual as f64 - mean_residual).sqrt() * 5.0;
