    // Slivers are defined as small remainders (1-15) which are hard to fill.
    if post > 0.0 && post < 15.0 {
        score += (15.0 - post) * 2.5;
    }

    // Dynamic adjustment based on stream progress. 
    // Near the end of the stream, we are more aggressive in packing to avoid opening new bins.
    let packing_urgency = (1.0 - progress).powf(0.5);

    // Lookahead logic: if the next item is large, penalize bins that leave too little space.
    if next_item_size > 0 {
        let next_item = next_item_size as f64;
        if post < next_item {
            score += (next_item - post) * 1.5 * packing_urgency;
        }
    }

    // If this is the only bin that can fit the item, prioritize it heavily.
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // If bin_residual == bin_capacity, this is a "new bin" candidate.
    // Penalize opening a new bin exponentially as we progress through the stream.
    if bin_residual == bin_capacity {
        score += 40.0 + (progress * 60.0);
    }

    // Favor bins that align with the current mean residual to keep bin density uniform.
    let deviation = (post - mean_residual).abs();
    score += deviation * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating "wasteland" space (too small for most items)
    // Small residuals are dangerous unless they are 0.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    }

    // Harmonic Class Logic: 
    // Reward packing such that the remaining space is a multiple of common item sizes.
    // If the next item can fit in the post_residual, drastically reduce score.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
        // Further reward if it creates a "perfect fit" for the next item
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // If this is a new bin, penalize it based on how many bins are already open
    // to encourage filling existing bins first.
    if bin_residual == bin_capacity {
        score += 25.0 + (open_bins_count as f64 * 2.5);
    }

    // Dynamic threshold: If fitting_bins_count is low, we are running out of options.
    // Be more aggressive in choosing a bin that leaves space for future items.
    if fitting_bins_count <= 2 {
        score -= 10.0;
    }

    // Use mean_residual to balance the load. If the current bin is 'emptier' than average,
    // it is a better candidate to keep open.
    if (bin_residual as f64) > mean_residual {
        score -= 5.0;
    }

    // Modulo-based penalty: Avoid residuals that are "awkward" (e.g., 1/3 or 1/4 of capacity)
    // because they often prevent larger items from fitting.
    if post_residual % 25 == 0 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Avoidance: Penalize post-residuals that are too small to fit typical future items
    // (e.g., 1-9 is often 'dead' space in many distributions).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 0.1);
    }

    // 2. Open Bin Pressure: Discourage opening new bins unless the fit is excellent.
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty
    // unless there are no other options or the fit is near-perfect.
    if bin_residual == bin_capacity {
        score += 45.0 + (open_bins_count as f64 * 2.5);
    }

    // 3. Lookahead Integration: If next_item_size is large, favor keeping larger residuals open.
    if next_item_size > 0 && next_item_size > post_residual {
        score += 20.0;
    }

    // 4. Fitting Density: If this is the last fitting bin, prioritize it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 5. Mean Deviation: Discourage bins that deviate significantly from the global mean residual.
    // This helps maintain a uniform fill rate across the bin set.
    score += (post_residual as f64 - mean_residual).abs() * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize bins that leave behind small, unusable slivers.
    // If post_residual is in the 1-9 range, it's highly likely to be wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead Matching: Reward placing items such that the next item fits perfectly
    // or leaves a minimal residue in the current bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward if the lookahead item fits in the space we are about to create.
            score -= (next_item_size as f64) * 0.8;

            // Further reward if it fills the bin almost perfectly.
            let remaining_after_next = (post_residual - next_item_size) as f64;
            if remaining_after_next < 5.0 {
                score -= 20.0;
            }
        }
    }

    // 3. Mean Residual Balancing: Penalize deviations from the average bin state.
    // This prevents creating a single very full bin while leaving others mostly empty.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    // 4. Scarcity Handling: If this is the only bin that can fit the item, 
    // heavily incentivize using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    // 5. New Bin Thresholding: Penalize opening a new bin unless the current 
    // open bins are all very poor fits.
    if bin_residual == bin_capacity {
        // Only consider a new bin if the average residual of existing bins is already small
        // or if we are near the end of the stream.
        let progress = step_index as f64 / total_items as f64;
        score += 40.0 + (progress * 20.0);

        // If we have many open bins, penalize opening another one.
        score += (open_bins_count as f64) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // 1. Best-Fit Penalty: Penalize large post_residuals (wasted space)
    // We emphasize tightly packed bins by squaring the post_residual
    score += (post_residual as f64).powi(2) * 0.05;

    // 2. Lookahead Integration: If the next item fits in the current post_residual,
    // reward this bin to preserve future capacity in other bins.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 1.5;
    }

    // 3. Global State Balancing:
    // If we have many open bins, we become more aggressive in filling existing ones.
    // If mean_residual is low, we are already efficient; don't open new bins unnecessarily.
    if !is_new_bin {
        score -= (mean_residual * 0.5);
    } else {
        // High penalty for opening a new bin if we have fitting options
        score += (open_bins_count as f64) * 2.0;
        // As the stream nears the end, opening a new bin is increasingly costly
        score += progress * 50.0;
    }

    // 4. Critical Threshold Logic:
    // If this is the only bin that fits the item, make it highly attractive
    // to prevent the forced opening of a new bin later.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 100.0;
    }

    // 5. Fragmentation Avoidance:
    // Penalize post_residuals that fall into the "useless" range (e.g., < 10)
    // unless it hits exactly 0 (perfect fit).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize the new bin heavily early on, but allow it to compete if the fit is poor.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        // As the stream progresses, the cost of opening a new bin decreases slightly 
        // to mitigate "fragmentation trap" at the end of the stream.
        45.0 - (progress * 15.0)
    } else {
        0.0
    };

    // Non-linear coupling: Use post_residual to favor tight fits, but penalize "dead zones"
    // (e.g., leaving 1-9 units is usually worse than leaving 0 units).
    let mut score = post + (post * post / 10.0);

    // Lookahead logic: If the next item is large, avoid creating a residual that is 
    // too small to accommodate it (e.g., post < next_item_size).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0 * (1.0 - progress);
    }

    // Encourage balanced bin usage: penalize bins that deviate significantly from the mean_residual
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.5;

    // If this is the only bin that fits the item, make it highly attractive to avoid 
    // unnecessary new bin allocation unless the fit is extremely poor.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    score + new_bin_penalty
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

