        // Base cost for opening a new bin is high to encourage filling existing ones.
        score += 35.0;
        // If the mean residual of existing bins is already small, opening a new bin is less harmful.
        score -= (mean_residual * 0.5);
        // As the stream nears completion, reduce the penalty for opening a new bin.
        score -= (progress * 20.0);
    }

    // Harmonic refinement: discourage creating residuals that are multiples of common item sizes 
