    }

    // 6. Progressive packing: As we near the end of the stream, prioritize closing bins over efficiency.
    let progress = step_index as f64 / total_items as f64;
    score -= (progress * 20.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Archetype: Aggressive 2-step lookahead matching.
    // Goal: Minimize post_residual, but prioritize bins that leave exactly enough space 
    // for the next item or minimize the creation of "fragmented" space (< 10).

    let mut score = post_residual as f64;

    // 1. Penalize opening a new bin prematurely unless we are forced to.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 45.0; 
    }

    // 2. Lookahead: If the post_residual is a perfect or near-perfect fit for the next item,
    // reward this bin significantly to preserve better space for other items.
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        if post_residual >= next_item_size {
