            score += 5.0;
        }
    }

    // 3. Penalty for "Dead Space": Residuals < 10 are often unusable.
    // We penalize bins that leave tiny slivers of space.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // 4. Global context: If fitting_bins_count is low, we are running out of options
