    }

    // 5. Mean-residual alignment: If this bin's post_residual is significantly 
    // higher than the current mean, we penalize it to encourage packing tighter bins.
    if (post_residual as f64) > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.5;
    }

    score
