    // be more aggressive about packing into existing bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (1.0 - progress) * 10.0;
    }

    // 4. New Bin Logic: If this is an empty bin (bin_residual == bin_capacity),
    // only choose it if we have no good options.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if an existing one can fit the item.
            score += 60.0 + (mean_residual * 0.5);
        } else {
            // If no other bin can fit it, prioritize the new bin but add a small constant.
            score += 5.0;
        }
    }

    // 5. Global State Balancing: Avoid opening too many bins early.
    score += (open_bins_count as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
