        score -= 10.0;
    }

    // 5. New Bin Logic: If bin_residual == bin_capacity, this is a fresh bin.
    // We only open a new bin if the score is lower than existing fits.
    // We penalize new bins based on the current progression (cost increases as we approach end of stream)
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items as f64;
        score = 45.0 + (progress * 10.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

