    // We heavily penalize small residuals late in the stream as they are unlikely to be filled.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_res) * (1.0 + 2.0 * progress);
    }

    // Lookahead logic: If the next item could fit in this bin, reward that bin.
    // We prioritize bins that can accommodate the next item to minimize fragmentation.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.5;
    }

    // If this is a new bin (bin_residual == bin_capacity), penalize opening it 
    // unless the current fitting options are extremely poor.
    if bin_residual == bin_capacity {
        // High penalty for opening new bins early, scaling down as the stream progresses.
        // We compare against the mean_residual of existing bins to decide if the new bin
        // is actually "cleaner" than the current mess.
        let openness_penalty = 40.0 * (1.0 - progress);
        score += openness_penalty;

        // If we have many open bins, opening another is costly.
        score += (open_bins_count as f64) * 2.0;
    } else {
        // If it's an existing bin, reward bins that are closer to the mean residual
        // to keep bin fullness balanced (load balancing).
        let imbalance = (post_res - mean_residual).abs();
        score += imbalance * 0.1;
    }

    // If this is the last chance for this item (fitting_bins_count == 1), 
    // force a slight preference to keep it.
    if fitting_bins_count == 1 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
