    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit Penalty: Penalize large gaps (waste)
    // We favor post_residuals that are close to 0 (tight fit).
    score += post_residual as f64 * 0.5;

    // 2. Lookahead Synergy: If the next item fits into the current post_residual,
    // reward this bin heavily to create a "perfect pair".
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 1.5;
    }

    // 3. Global State Balancing:
    // If we have many open bins, we become more aggressive in packing tightly (Best-Fit).
    // If we are at the end of the stream, we prioritize closing bins to reduce total count.
    score += (open_bins_count as f64) * 0.2 * (1.0 - progress);

    // 4. New Bin Thresholding:
    // If this is a new bin (bin_residual == bin_capacity), penalize it based on how many
    // other bins could have taken the item. Only open a new bin if the existing
    // options are truly terrible (high post_residual).
    if bin_residual == bin_capacity {
        score += 25.0; // Base cost to open a new bin
        score -= (fitting_bins_count as f64) * 5.0; // Reduce cost if no other options exist
    } else {
        // 5. Fragmentation Avoidance:
        // If this bin is the last one that can fit the item (fitting_bins_count == 1),
        // we might want to save it for a potentially harder-to-fit item later,
        // but generally, taking the fit is safer.
        if fitting_bins_count == 1 && post_residual < 15 {
            score -= 10.0; // Priority to lock in a tight fit
        }
    }

    // 6. Mean Residual Correction:
    // If the current bin's residual is significantly worse than the average,
    // penalize placing the item here to avoid "killing" a healthy bin.
    if (bin_residual as f64) > mean_residual {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the post_residual (Best Fit principle)
    let mut score = post_residual as f64;

    // Penalty for opening a new bin: proportional to the progress (as bins fill, opening new ones is costlier)
    // We dampen this penalty if the current bin is the only one that can fit the item to avoid unnecessary fragmentation.
    if is_new_bin {
        score += 25.0 + (progress * 45.0);
        if fitting_bins_count > 0 {
            score += 100.0 * (1.0 - progress);
        }
    } else {
        // Reward bins that have a residual close to the next item size (Lookahead coupling)
        if next_item_size > 0 && post_residual >= next_item_size {
            let diff = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 / (1.0 + diff));
        }

        // Penalize creating "dead zones" (residuals too small for common items, e.g., < 10)
        // We use a non-linear sigmoid-like push for residuals that are unusable
        if post_residual > 0 && post_residual < 10 {
            score += (10.0 - post_residual as f64) * 5.0;
        }

        // Coupling with global state: penalize if this bin's residual deviates significantly from the mean
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += 0.2 * deviation;
    }

    // Dynamic pressure: as we approach the end of the stream, prioritize tightest fits (Best Fit)
    // more aggressively by dampening the penalties for new bins.
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: Penalize large post_residuals (dead space)
    // 2. Harmonic/Modulo logic: Favor residuals that align with common item size multiples (e.g., 20, 25, 50)
    // to keep bins "compatible" for future items.
    let residual_penalty = (post_residual % 25) as f64 * 0.5;
    score += residual_penalty;

    // 3. Lookahead Logic: If the next item can fit in the current post_residual, drastically reduce score.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0;
    }

    // 4. Scarcity/Efficiency: If this is the only fitting bin, prioritize it to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // 5. New Bin Threshold: If bin is empty (new bin candidate), set a baseline cost based on total utilization.
    // Higher total_items progression increases the penalty for opening new bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items as f64;
        score = 35.0 + (progress * 25.0);
    }

    // 6. Mean Residual Balancing: Penalize bins that deviate too far from the average state,
    // encouraging uniform packing across all open bins.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: If post_residual is in the range (0, 10), it is likely to be wasted.
    // We penalize these "sliver" residuals heavily to force tight fits.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64);
    }

    // 2. Lookahead Synergy: If the next item fits in the current post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. Open Bin Pressure: Penalize opening new bins when current ones are available.
    // If we are considering a new bin (bin_residual == bin_capacity), increase its cost 
    // proportional to how many bins are already open to discourage fragmentation.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 1.5;
    }

    // 4. Tightness Bias: Reward bins that are already "fuller" than the average open bin 
    // to consolidate items into a smaller set of active bins.
    if (bin_capacity - bin_residual) as f64 > (bin_capacity as f64 - mean_residual) {
        score -= 5.0;
    }

    // 5. Last Chance Heuristic: If this is the only bin that fits the item, make it highly attractive.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. If this is a new bin, penalize based on the current open count and the mean residual.
    // We want to avoid opening new bins unless the current bins are very full (low mean_residual).
    if bin_residual == bin_capacity {
        score += 50.0 + (mean_residual * 2.0) + (open_bins_count as f64 * 0.5);
    } else {
        // 2. Best-Fit logic: prioritize bins where post_residual is small (tight fit).
        // Penalize bins that leave a "dead zone" (e.g., 1-9 remaining) if the next item is large.
        if post_residual > 0 && post_residual < 10 {
            score += 40.0; 
        }

        // 3. Lookahead matching: if the post_residual is close to the next_item_size,
        // reward this bin as it sets up a perfect subsequent fit.
        if next_item_size > 0 {
            let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
            score += diff * 0.8;

            // If the current bin can fit the next item after this one, favor it.
            if post_residual >= next_item_size {
                score -= 15.0;
            }
        }

        // 4. Pressure valve: if this is the last fitting bin, prioritize it to avoid 
        // unnecessary new bin creation.
        if fitting_bins_count == 1 {
            score -= 25.0;
        }
    }

    // 5. Progression scaling: as we near the end of the stream, be more conservative 
    // about opening new bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit logic: Penalize large post_residuals (wasted space)
    // We favor tight fits (post_residual near 0).
    score += (post_residual as f64).powf(1.2);

    // 2. Lookahead mechanism: If the next item fits into the current post_residual, 
    // prioritize this bin heavily to avoid fragmentation.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 1.5;
    }

    // 3. Global state: If we are near the end of the stream, be more aggressive
    // about filling existing bins to minimize the total count.
    if progress > 0.8 {
        score -= (bin_capacity - post_residual) as f64 * 0.5;
    }

    // 4. Penalty for opening new bins: Only open a new bin if the post_residual
    // of existing bins is significantly suboptimal for future items.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Only open a new bin if we have very few options or if current bins are too fragmented
        if fitting_bins_count > 0 {
            score += 45.0 + (mean_residual * 0.5);
        } else {
            score -= 10.0;
        }
    }

    // 5. Fragmentation avoidance: If only one bin can fit this item, 
    // prioritize it to save that bin for future, potentially larger items.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    // 6. Balance the load: Penalize bins that deviate too much from the mean_residual
    // to keep the bin distribution uniform.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the remaining space (Best Fit principle).
    let mut score = post;

    // Penalty for creating "dead space" (very small residuals that are unlikely to fit future items).
    // We penalize residuals in the [1, 9] range more heavily as the stream progresses.
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * (1.0 + 2.0 * progress);
    }

    // Lookahead logic: if the next item is large, avoid leaving a residual that is too small for it.
    if next_item_size > 0 {
        if post > 0.0 && post < next_item_size as f64 {
            score += (next_item_size as f64 - post) * 1.5;
        }
    }

    // Dynamic thresholding for new bin creation:
    // If this is a new bin (bin_residual == bin_capacity), calculate an "opportunity cost"
    // based on how well the item fits into existing bins.
    if bin_residual == bin_capacity {
        // If there are many bins that could fit this item, opening a new one is inefficient.
        // We make the new bin score higher (worse) based on fitting_bins_count.
        score = 50.0 + (fitting_bins_count as f64 * 15.0);

        // As the stream nears the end, opening new bins becomes increasingly expensive.
        score += progress * 100.0;
    } else {
        // Reward filling bins that are already closer to the mean residual of the system
        // to keep bin utilization uniform.
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score -= deviation * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating 'dead space' (fragments smaller than the smallest likely item)
    // We prioritize bins where the post_residual is a multiple of common item sizes (harmonic fit)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // If this is a new bin, apply a threshold penalty based on how many existing bins 
    // are capable of taking the current item. Opening a new bin is expensive.
    if bin_residual == bin_capacity {
        score += (fitting_bins_count as f64) * 25.0;
        // Discourage opening new bins too early in the stream
        score += (1.0 - (step_index as f64 / total_items as f64)) * 10.0;
    }

    // Lookahead logic: if next_item_size is large, favor bins that leave enough space
    // for it, or conversely, pack the current item into a bin that leaves little room
    // if the next item is also small.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can accommodate the next item (synergy)
            score -= 15.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            // Penalty for stranding the next item
            score += 20.0;
        }
    }

    // Harmonic load balancing: penalize bins that deviate significantly from the mean_residual
    // to encourage uniform fill across the set of open bins.
    let dev = (bin_residual as f64 - item_size as f64 - mean_residual).abs();
    score += dev * 0.5;

    // Heavily penalize bins that are nearly empty if we have many open bins already
    if bin_residual == bin_capacity && open_bins_count > 5 {
        score += 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
