        // Penalize opening a new bin proportional to how many bins are already open.
        score += (open_bins_count as f64) * 15.0;

        // If we have many bins with large residuals, opening a new one is inefficient.
        score += mean_residual * 0.5;
    } else {
        // Favor bins that have residuals close to the mean to keep bin usage density uniform.
        let residual_diff = (bin_residual as f64 - mean_residual).abs();
        score += residual_diff * 0.1;
    }

    // 4. Scarcity avoidance: If this is the only bin that can fit the item, prioritize it heavily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
