    // as they create "islands" that cannot fit typical items (10-80).
    // We favor post_residuals that are either 0 (perfect fit) or >= 20.
    if post_residual > 0 && post_residual < 20 {
        score += 45.0 + (20.0 - post_residual as f64) * 2.5;
