    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead Coupling: If next_item_size is known, favor bins that can accommodate it.
    // If post_residual is close to next_item_size, we reward this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward exact or near-exact matches for the next item
            score -= (100.0 - (post_residual as f64 - next_item_size as f64).abs());
        } else {
            // Penalize bins that would be unable to fit the next item
            score += 20.0;
        }
    }

    // 3. Global Efficiency: If this is the only bin that fits the current item, 
    // prioritize it heavily to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // 4. Mean Residual Balancing: Avoid creating bins that are outliers compared to the mean.
    // If the post_residual is significantly higher than the mean, penalize to keep bins tight.
    if (post_residual as f64) > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.5;
    }

    // 5. New Bin Thresholding: Discourage opening a new bin unless the current fit is catastrophic.
    if bin_residual == bin_capacity {
        // Only consider a new bin if the current progression is early or 
        // if the current fitting options are extremely poor.
        score += 40.0;
        if open_bins_count > 0 {
            score += 30.0 * (1.0 - (step_index as f64 / total_items as f64));
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
