    };

    // Dynamic thresholding: as the stream progresses, become increasingly conservative
    // about opening new bins, penalizing the empty bin candidate (bin_residual == bin_capacity).
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        (open_bins_count as f64 * 0.5) + (progress * 20.0)
    } else {
        0.0
    };

    // Use mean_residual to balance the bin load. 
    // Prefer bins closer to the current mean to keep bin states uniform.
    let load_balance = (post_res - mean_residual).abs() * 0.1;

    // Combine terms:
    // 1. Primary: post_residual (Best Fit logic)
    // 2. Secondary: gap_penalty (avoid slivers)
    // 3. Tertiary: lookahead_factor (reserve space for known future)
    // 4. Global: new_bin_penalty (discourage fragmentation)
    let mut score = post_res + gap_penalty + (lookahead_factor * 10.0) + new_bin_penalty + load_balance;

    // If this is the only bin that fits, reduce its score significantly to prioritize 
    // using existing resources before opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
