    } else {
        // Reward bins that are closer to the mean residual to keep bin fullness balanced
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.1;
    }

    // Progression scaling: as we approach the end of the stream, prioritize space consolidation
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

