    // Lookahead logic: if next_item_size is large, favor bins that can accommodate it.
    // If post_residual is smaller than next_item_size, we penalize the bin slightly.
    if next_item_size > 0 {
        if post < next_item_size as f64 {
            score += (next_item_size as f64 - post) * 0.5;
        }
    }

    // Dynamic thresholding: as the stream progresses, be more conservative about opening new bins.
    // If bin_residual == bin_capacity, this is a new bin. Penalize it proportional to progress.
    if bin_residual == bin_capacity {
        // As we reach the end of the stream, the cost of opening a new bin increases to force packing.
        score += 25.0 * (1.0 + progress);
    }

    // Coupling with mean_residual: avoid bins that deviate significantly from the mean,
    // as we want to keep residual distributions uniform to maximize packing flexibility.
    let dev = (post - mean_residual).abs();
    score += dev * 0.2;

    // If this is the last fitting bin, slightly reward it to prevent opening unnecessary new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base penalty for creating "fragmented" space (too small for most items)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Harmonic lookahead: Penalize placements that block the next item from fitting
    // If the next item is large, we want to reserve larger residuals.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 40.0;
        } else {
            // Reward bins that leave exactly enough space for the next item (synergy)
            if post_residual >= next_item_size && post_residual < (next_item_size + 15) {
                score -= 25.0;
            }
        }
    }

    // 3. Efficiency heuristic: Prefer bins that are already "tight"
    // Use the mean_residual to identify bins that are becoming too empty
    if (bin_residual as f64) > mean_residual {
        score += 5.0;
    }

    // 4. Strategic new bin opening logic
    // If we only have one fitting bin but it leaves a very awkward residual, 
    // allow a new bin to compete if the current fit is extremely poor.
    if bin_residual == bin_capacity {
