        score = 35.0 + (open_bins_count as f64 * 2.0);
    } else {
        // Penalize using the last fitting bin if it creates a dead zone
        if fitting_bins_count == 1 && post_residual < 15 && post_residual > 0 {
            score += 30.0;
        }
    }

    // 5. Progress-based scaling: Be more conservative as the stream nears the end
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
