    // We apply a non-linear exponential penalty for gaps in the [1, 15] range
    if post > 0.0 && post < 15.0 {
        score += (15.0 - post).powi(2) * 2.5;
    }

    // Lookahead coupling: If next item is large, penalize small post_residual
    if next_item_size > 0 {
        let next = next_item_size as f64;
