    // Balancing: Favor bins that keep the mean_residual close to the item_size,
    // reducing variance across bins to prevent "fragmentation" of residuals.
    let residual_diff = (post - mean_residual).abs();
    score += residual_diff * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
