    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // 4. Global State Awareness:
    // If this is the only bin that fits the current item, prioritize it 
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // 5. Dynamic Horizon: As the stream nears completion, become more aggressive 
    // about filling existing bins to minimize the total count.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (1.0 - progress) * 10.0;
    }

    // 6. New Bin Threshold:
    // If this is a new bin (residual == capacity), penalize it significantly
    // unless no other bins can accommodate the item.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 100.0;
        } else {
            score -= 20.0; // Accept new bin only if necessary
        }
    }

    // 7. Load Balancing: Favor bins that stay near the mean residual 
    // to keep the capacity distribution uniform.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the post_residual (Best Fit principle)
    // We penalize small residuals that are likely to become stranded (dead space)
    // A residual between 1 and 9 is often unusable for items >= 10.
    let mut score = post;

    // Penalty for creating unusable space (under 10 units)
    if post > 0.0 && post < 10.0 {
        score += 50.0 * (1.0 - (post / 10.0));
    }

    // Lookahead logic: if next_item_size is large, favor larger residuals (smaller post)
    // If next_item_size is small, favor filling bins tightly.
    if next_item_size > 0 {
        let lookahead_diff = (next_item_size as f64 - post).abs();
        score += lookahead_diff * 0.2;
    }

    // Dynamic pressure: As the stream progresses, increase the cost of opening new bins
    // by penalizing the "new bin" case (where bin_residual == bin_capacity)
    if bin_residual == bin_capacity {
        // The cost of a new bin increases as we approach the end of the stream
        // to encourage consolidation.
        score += 25.0 * (1.0 + progress);
    }

    // Coupling: If fitting_bins_count is low (e.g., 1), we are forced to pick this bin
    // or open a new one. We reduce score to favor using existing bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Penalize bins that deviate significantly from the mean residual to keep packing uniform
    let residual_variance = (post - mean_residual).abs();
    score += residual_variance * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

