    // We apply a base cost of the post_residual squared to punish large gaps.
    score = (post_residual * post_residual) as f64;

    // 2. Harmonic Lookahead: If next_item_size is known, prioritize leaving space for it.
    // If post_residual is slightly less than next_item_size, it's a "bad" fit (fragmentation).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalize creating a gap that is too small for the next item
            score += (next_item_size - post_residual) as f64 * 15.0;
        } else {
            // Reward creating a gap that fits the next item perfectly (Best Fit for next)
            let remaining_after_next = post_residual - next_item_size;
            score += (remaining_after_next * remaining_after_next) as f64 * 0.5;
        }
    }

    // 3. Fragmentation Control: Avoid creating "unusable" small gaps (1..9).
    // Small residuals are often wasted. If post_residual is in (0, 10), penalize.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 4. New Bin Logic: If bin_residual == bin_capacity, we are evaluating a brand new bin.
    // We only want to open a new bin if the existing bins are "crowded" or if the current
    // fit is significantly worse than leaving a new bin open.
    if bin_residual == bin_capacity {
        // High penalty for opening new bins; only do so if open_bins_count is low
        // or if we are late in the sequence to avoid fragmentation.
        score += 200.0 + (open_bins_count as f64 * 2.0);
    } else {
        // Reward filling existing bins to minimize total_bins_count.
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    }

    // 5. Fitting Constraint: If this is the last bin that can fit the item, 
    // force its selection by lowering the score significantly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
