    if fitting_bins_count == 1 && post_residual < 5 && bin_residual != bin_capacity {
        score += 100.0;
    }

    // 5. New Bin Thresholding: Discourage opening a new bin unless the current mean residual 
    // is already quite low, indicating that existing bins are becoming fragmented.
    if bin_residual == bin_capacity {
        // If we have many open bins, penalize opening a new one.
        score += (open_bins_count as f64) * 5.0;
        // If the mean residual of existing bins is already small, we are forced to open a new one.
        score -= mean_residual * 0.5;
    }

    // 6. Progress Scaling: As the stream nears the end, prioritize closing bins to reduce total count.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead space penalty: Heavily penalize small gaps that are unlikely to fit future items.
    // Gaps < 10 are effectively dead space since min item size is 10.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. Lookahead optimization: If the next item can fit in the post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
