        // or if we have very few bins open.
        if mean_residual > 20.0 && open_bins_count > 2 {
            score += 40.0 + open_bin_penalty;
        } else {
            score += 15.0 + open_bin_penalty;
        }
    } else {
        // 5. Existing bin preference: Favor bins that leave larger, more flexible gaps.
        // Subtract to make these lower scores (higher priority).
        score -= (bin_capacity - post_residual) as f64 * 0.1;

        // Penalize bins that are "last chance" if they result in poor residual space.
        if fitting_bins_count == 1 && post_residual < 15 {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
