    // We apply a non-linear penalty for residuals that are too small to fit common future items.
    if post > 0.0 && post < 10.0 {
        score += 50.0 / (post + 1.0);
    }

    // Lookahead coupling: If next_item_size is large, penalize bins that cannot accommodate it
    // after the current placement.
    if next_item_size > post_residual && next_item_size > 0 {
        score += 25.0 * (next_item_size as f64 / (post + 1.0));
    }

    // Stream progression adjustment: As we approach the end of the stream, 
    // prioritize consolidating items into fewer bins even if fit quality is slightly worse.
    let consolidation_pressure = progress * 20.0;
    score -= consolidation_pressure * (open_bins_count as f64 / 10.0);

    // New bin logic: If bin_residual == bin_capacity, we are evaluating opening a new bin.
    // We only want to open a new bin if the current open bins are "too full" to handle 
    // the next item effectively.
    if bin_residual == bin_capacity {
        // If there are fitting bins, heavily penalize opening a new one unless 
        // they are all extremely inefficient.
        if fitting_bins_count > 0 {
            score += 60.0 + (mean_residual * 0.5);
        } else {
            // No bins fit, so this is a forced new bin; make it the lowest score.
            score = -100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
