        let fit_diff = (post_residual - next_item_size) as f64;
        score -= 200.0 * (1.0 / (1.0 + fit_diff));
    }

    // 3. New Bin Penalty: If this is a new bin, penalize it relative to the average state.
    // This forces the algorithm to exhaust existing bins before opening new ones unless
    // the residual space in current bins is significantly worse than an empty bin.
    if bin_residual == bin_capacity {
        score += 85.0; 
        // If we are at the very end of the stream, discourage opening new bins.
        let progress = step_index as f64 / total_items as f64;
        score += progress * 50.0;
    }

    // 4. Mean Residual Coupling: If this bin's post_residual is significantly better than 
    // the current mean_residual, reward it to encourage uniformity.
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 0.5;
    }

    // 5. Last Chance Logic: If this is the last bin that can fit the item, 
    // provide a slight priority boost to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
