pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize the "New Bin" candidate (bin_residual == bin_capacity) 
    // to force utilization of existing space unless the fit is extremely poor.
    let mut score = if bin_residual == bin_capacity {
        // As the stream progresses, we become more desperate to open new bins to avoid fragmentation.
        // Penalty decreases as progress increases.
        25.0 - (progress * 10.0)
    } else {
        // Best-Fit Decreasing logic: reward smaller post_residual.
        // We use a quadratic term to heavily penalize large gaps (waste).
        (post * post) / 10.0
    };

    // Lookahead influence: If the next item is large, avoid leaving a tiny, unusable residual.
    if next_item_size > 0 {
        let gap_penalty = if post_residual < next_item_size {
            // If the next item cannot fit, the current residual is "wasted" (fragmented).
            // Penalize this more if we are early in the stream.
            (1.0 - progress) * 15.0
