            // If the next item fits, reward keeping the residual close to the next item's size.
            let diff = (post_residual as f64 - next_item_size as f64).abs();
            -diff * 0.5
        };
        score += gap_penalty;
    }

    // Interaction with global state: 
    // If few bins fit the current item, prioritize using one of them to prevent opening unnecessary bins.
    if fitting_bins_count > 0 && bin_residual < bin_capacity {
        score -= (fitting_bins_count as f64).ln() * 2.0;
    }

    // Final adjustment: Penalize creating bins that deviate significantly from the mean residual
    // to maintain a uniform distribution of fill levels across open bins.
    let residual_deviation = (post - mean_residual).abs();
    score += residual_deviation * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
