    // Adjust for the end of the stream: if nearing the end, prioritize consolidating
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize post_residual, but heavily penalize small gaps (1-9) that are hard to fill.
    // We favor bins that leave either 0 space or enough space for the next item.

    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post_residual as f64;

