        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.2;
    }

    // 4. Progress-aware scaling: As the stream nears completion, become more
    // aggressive about filling existing bins to avoid leftover empty bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (1.0 - progress) * 20.0;
