    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score = 0.0;
        } else {
            // Only open a new bin if the mean residual of existing bins is already very tight (< 15)
            // or if the current item is large (e.g., > 60).
            score += 40.0 + (mean_residual * 0.5);
            if item_size > 60 {
                score -= 20.0;
            }
        }
    }

    // 4. Fitting Constraint: 
    // If this is the ONLY bin that can fit the item, prioritize it heavily to avoid unnecessary new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 5. Progression scaling:
    // As the stream nears completion, become more aggressive about filling existing bins 
    // to minimize the trailing open bin count.
    let progress = step_index as f64 / total_items as f64;
    score += (progress * 10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
