        }
    }

    // 4. Fitting count constraint: If this is the only bin that fits the current item, 
    // prioritize it heavily to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 5. Global state normalization: Penalize deviations from mean_residual to keep 
    // bin fill levels balanced (Best-Fit-like behavior).
    let diff = (post_residual as f64 - mean_residual).abs();
    score += diff * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base Strategy: Best Fit Decreasing (BFD) logic.
    // We prefer bins that result in smaller post_residuals.

    // 2. Penalty for opening a new bin unnecessarily:
    // If this is a new bin (bin_residual == bin_capacity) and there are bins that can fit the item,
    // penalize the score heavily to discourage fragmentation.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 150.0;
    }

    // 3. Lookahead Matching (The "Aggressive 2-step" logic):
    // If we have a next item, we want to prioritize bins that leave exactly enough space
    // for the next item, or minimize the wasted gap between the current post_residual and next_item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can accommodate the next item perfectly (gap of 0).
            let gap = (post_residual - next_item_size) as f64;
            score += gap * 0.5;
        } else {
            // If the post_residual is too small to hold the next item, penalize it
            // proportionally to the "lost opportunity" size.
            score += (next_item_size - post_residual) as f64 * 1.2;
        }
    }

    // 4. Mean Residual Balancing:
    // Avoid creating bins that deviate significantly from the current mean state,
    // which helps in keeping bin utilization uniform across the open set.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    // 5. Progression Weighting:
    // As we approach the end of the stream, prioritize closing bins (lower residual)
    // more aggressively to avoid leaving many half-filled bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
