            // Reward keeping space for the next item
            score -= (next_item_size as f64) * 0.5;
        }
    }

    // Scaling factor based on bin density utilization
    let utilization = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= utilization * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score: punish large post-residuals (Best Fit logic)
    let mut score = post_residual as f64;

    // Penalize the new bin disproportionately early in the stream, 
    // but allow it late if open bins are too fragmented.
    if is_new_bin {
        score += 15.0 + (35.0 * (1.0 - progress));

        // If we are forced to open a bin because no other bin fits, lower the penalty
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    } else {
        // Favor bins that leave space for the next item (Lookahead)
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
            } else {
                // If the next item cannot fit, we create "dead space"
                score += 5.0 * (1.0 - progress);
            }
        }

        // Non-linear coupling: penalize bins that deviate significantly from the mean_residual
        // to encourage packing uniformity across open bins.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += 0.5 * deviation.powf(1.5);
    }

    // Dynamic threshold: If we have many open bins, prioritize clearing them out
    score += (open_bins_count as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for leaving "unusable" small gaps (1-9) which are hard to fill
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Harmonic preference: prioritize bins that leave space for the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward perfect or near-perfect fit for the lookahead item
            score -= (bin_capacity - (post_residual - next_item_size)) as f64 * 0.5;
        } else {
            // Penalize bins that cannot accommodate the lookahead
            score += 25.0;
        }
    }

    // Logic for new bin vs existing: 
    // If it's a new bin (residual == capacity), penalize it based on how many bins are already open
    // to discourage fragmentation, unless the fit in existing bins is abysmal.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 15.0;
        // If there are many fitting bins, the new bin is a bad choice
        score += (fitting_bins_count as f64) * 40.0;
    }

    // Favor bins that align with the mean density of current open bins to keep utilization balanced
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    // Progression logic: as we approach the end, be more aggressive with packing
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    // Harmonic class penalty: avoid residues that are awkward divisors of the capacity
    if post_residual > 0 && (bin_capacity % post_residual) < 3 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Strict Dead Space Avoidance: Penalize gaps that are too small for common items (10-30 range)
    // If post_residual is in the "danger zone" (1..10), penalize heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 0.1);
    }

    // 2. Lookahead Coupling: If the next item can fit in the current post_residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. Open Bin Pressure: Discourage opening new bins unless necessary.
    // If this is a new bin (bin_residual == bin_capacity), apply a penalty based on existing open bins.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 2.5;
        // Only allow new bin if it's the only option or if existing bins are very tight.
        if fitting_bins_count > 0 {
            score += 40.0;
        }
    }

    // 4. Tight Fit Reward: If the item fills the bin almost perfectly, prioritize it.
    if post_residual == 0 {
        score -= 30.0;
    }

    // 5. Global Efficiency: If current bin is emptier than average, prioritize filling it to keep mean_residual balanced.
    if (bin_residual as f64) > mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing (BFD) core: prioritize smaller post_residual
    // 2. Penalty for creating "dead space": if post_residual < 10, it's likely unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 3. Lookahead Matching: If the next item fits perfectly into the new post_residual, 
    // reward this placement heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual > next_item_size {
            // Reward bins that leave just enough space for the next item
            score -= (10.0 * (next_item_size as f64 / (post_residual as f64 + 0.1)));
        }
    }

    // 4. Global Density Control: If fitting_bins_count is low, we are running out of options.
    // If this is a new bin (residual == capacity), penalize opening it unless necessary.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 50.0;
        } else {
            score -= 10.0;
        }
    }

    // 5. Mean-Residual Alignment: Penalize bins that deviate too far from the mean,
    // as these create uneven load distribution.
    let diff_from_mean = (post_residual as f64 - mean_residual).abs();
    score += diff_from_mean * 0.2;

    // 6. Progressive Tightening: As we reach the end of the stream, 
    // prioritize closing existing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best Fit Decreasing logic: heavily penalize large post_residual (wasted space)
    // We want to pack tightly.
    score += post_residual as f64 * 1.5;

    // 2. Lookahead mechanism: 
    // If the next item can fit in the current post_residual, prioritize this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 2.5;
    }

    // 3. Avoid small "slivers" (unusable space < 10)
    // Small residuals are usually dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // 4. Global state awareness:
    // If we have many open bins, prioritize filling existing ones (reduce open_bins_count).
    // If we are near the end of the stream, prioritize aggressive packing.
    if bin_residual < bin_capacity {
        score -= (open_bins_count as f64) * 0.5;
        score -= progress * 10.0;
    } else {
        // Penalty for opening a new bin
        score += 40.0;
        // If it's the only option, reduce penalty
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // 5. Mean residual balance:
    // Avoid bins that deviate significantly from the mean residual to keep distribution uniform.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the residual space remaining (lower is better, Best-Fit principle).
    let mut score = post;

    // Penalty for creating small, unusable gaps (fragmentation avoidance).
    // If post_residual is > 0 and < 10 (the minimum item size), it is likely wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (1.0 - (post / 10.0));
    }

    // Lookahead logic: if the next item is large, prioritize keeping more residual space available.
    if next_item_size > 0 {
        let next_item_f = next_item_size as f64;
        // If the current bin cannot fit the next item anyway, we don't care as much about keeping it empty.
        // If it CAN fit the next item, we reward keeping enough space.
        if post >= next_item_f {
            score -= 15.0 * (1.0 - (post - next_item_f) / bin_capacity as f64);
        }
    }

    // Dynamic scaling based on stream progression.
    // Early in the stream, we are aggressive about packing tightly.
    // Late in the stream, we become more conservative to avoid opening new bins.
    let progression_factor = 1.0 + (progress * 2.0);
    score *= progression_factor;

    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty
    // that scales down as the stream progresses (making it easier to open bins late-game).
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin is high.
        let new_bin_penalty = 80.0 * (1.0 - (progress * 0.5));
        score += new_bin_penalty;
    }

    // Coupling with fitting_bins_count: 
    // If this is the only bin that fits, we should prioritize it significantly (negative bias).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base penalty for leaving small, unusable gaps (The "Dead Space" penalty)
    // We penalize residuals that are too small to fit common small items (< 20)
    if post_residual > 0 && post_residual < 20 {
        score += (20.0 - post_residual as f64) * 2.5;
    }

    // 2. Harmonic Lookahead: If next_item_size is large, favor bins that can accommodate it.
    // We calculate "fit capacity" as post_residual. If the next item fits, reward the bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 1.5;
    }

    // 3. Harmonic balance: Favor bins that move toward the mean residual of the set.
    // This keeps bin packings uniform and prevents "outlier" bins.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.5;

    // 4. Scarcity avoidance: If this is the only bin that fits the current item, 
    // prioritize it heavily to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // 5. New Bin Thresholding:
    // If we are considering a new bin (residual == capacity), apply a threshold penalty 
    // based on how many items are left and how many bins are already open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items as f64;
        // Only open a new bin if we have many items left or if existing bins are very full
        score += 40.0 + (progress * 20.0) + (open_bins_count as f64 * 2.0);
    }

    // 6. Modulo alignment: Reward residuals that align with common item sizes (e.g., multiples of 25)
    // This creates "bins of 100" that are perfectly divisible by 4, 2, or 5.
    if post_residual % 25 == 0 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

