    // If post_residual is in [1, 9], this bin becomes effectively useless for future items.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. Penalize opening a new bin if an existing bin can fit the item.
    // This forces the logic to prioritize fitting into existing bins.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 200.0;
    }

    // 3. Pressure management: If we have many open bins, penalize opening more.
    if bin_residual == bin_capacity {
