    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            // Penalty for stranding a large item that cannot fit in this residual.
            score += 15.0;
        }
    }

    // 5. Prefer bins that keep the mean_residual high to maintain flexibility.
    // We reward bins that result in a post_residual closer to the mean_residual.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    // 6. Final bias: Favor tighter fits (Best Fit principle) by keeping the 
    // base post_residual weight, but adjusted by the fitting_bins_count.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        // High priority to finish off a bin that is the "last chance" for this item.
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
