    // it might be creating "dead space" that is too small for future items.
    // We penalize very small residuals that aren't zero, to avoid "fragmentation".
    if post_residual > 0 && (post_residual as f64) < (mean_residual * 0.5) {
        score += 25.0;
    }

    // 5. Urgency factor
    // If this is the only bin that fits, we are forced to take it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // 6. Progressive tightening
    // As we reach the end of the stream, prioritize closing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
