    // Penalize bins that deviate significantly from the mean residual of open bins,
    // encouraging a uniform "fill level" across the fleet.
    let residual_diff = (post_r - mean_residual).abs();
    score += 0.5 * residual_diff;

    // Favor bins that are closer to being full if we are nearing the end of the stream
    score -= (1.0 - progress) * (cap - post_r) * 0.1;

