    // 3. Open bins pressure: If this is a new bin (bin_residual == bin_capacity),
    // only choose it if the current best existing bin is extremely poor (high post_residual).
    if bin_residual == bin_capacity {
        // Base cost for opening a new bin is high to force packing into existing space.
        score = 45.0 + (open_bins_count as f64 * 0.5);
    } else {
