        if post_residual < next_item_size {
            score += 40.0;
        }
    }

    // 4. Global state: If we are late in the stream, be more aggressive about 
    // closing bins (Best-Fit) rather than opening new ones.
    if is_new_bin {
        score += 15.0 + (progress * 25.0);
        // Penalize opening a new bin if we have many open bins already
        score += (open_bins_count as f64) * 2.0;
    }

    // 5. Dynamic balancing: compare current bin residual to the global mean.
    // If this bin is significantly emptier than the average, prioritize filling it.
    if !is_new_bin {
        if bin_residual > (mean_residual as u32) {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score: Favor smaller post_residual (Best Fit principle).
    let mut score = post;

    // Penalty for leaving a 'dead zone' that is too small for any likely future item.
    // We use the mean_residual as a dynamic threshold.
    if post > 0.0 && post < 10.0 {
        score += 25.0 * (1.0 - (post / 10.0));
    }

    // Lookahead logic: If the next item is large, prioritize bins that can accommodate it.
    // If current bin can't fit next item, penalize leaving a small residual.
    if next_item_size > 0 && post < next_item_size as f64 {
        score += (next_item_size as f64 - post) * 0.5;
    }

    // Dynamic thresholding based on stream progress:
    // Early in the stream, be conservative (fill bins tightly).
    // Late in the stream, allow slightly worse fits to consolidate remaining space.
    let consolidation_factor = (1.0 - progress) * 15.0;
    score += (post - mean_residual).abs() * consolidation_factor;

    // New bin logic:
    // If bin_residual == bin_capacity, we are evaluating opening a new bin.
    // Only open a new bin if the current best existing bin is extremely inefficient.
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score = 0.0;
        } else {
            // High penalty for opening a new bin unless existing bins are very full.
            score = 40.0 + (mean_residual * 0.5);
        }
    } else {
        // If this is the only bin that can fit the item, give it a massive priority boost.
        if fitting_bins_count == 1 {
            score -= 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual (Best Fit principle)
    // The base score (post_residual) already favors tight packing.

    // 2. Lookahead Logic: If next_item_size fits in the remaining space, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0;
    }

    // 3. Fragmentation Avoidance: If post_residual is small but > 0, it creates "dead space" 
    // that cannot fit most items (min item size is typically 10-20).
    // Penalize small gaps that are likely to be wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 35.0;
    }

    // 4. Harmonic Alignment: Favor bins where the post_residual is a multiple of common item sizes 
    // or aligns with the remaining capacity to allow future pairs.
    if post_residual > 0 {
        score += (post_residual % 20) as f64 * 0.5;
    }

    // 5. Global Load Balancing: Avoid opening new bins unless necessary.
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty
    // unless there are no other options (fitting_bins_count == 0).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 60.0 + (open_bins_count as f64 * 1.5);
        } else {
            // No choice, must open new bin.
            score = 0.0;
        }
    }

    // 6. Progression-aware refinement: As we approach the end of the stream, 
    // prioritize tighter packing more aggressively.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
