    // Lookahead logic: if the next item can fit in the current post_residual, prioritize this bin
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
        // Bonus for "perfect" fit for the next item
        if post_residual == next_item_size {
            score -= 10.0;
        }
    }

    // Heuristic: avoid creating "sliver" residuals (1..9) that are hard to fill
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Pressure adjustment: if few bins can fit the current item, prioritize keeping current bins open
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // Dynamic adjustment based on global state: align with mean_residual to balance fragmentation
    // If our post_residual is significantly lower than the mean, we are creating a tight bin
    if (post_residual as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += 2.0;
    }

    // Progress scaling: tighten behavior towards the end of the stream
    let progress = step_index as f64 / total_items as f64;
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // We aim to minimize the score.
    // 1. Base penalty: The residual space left after placement (Best Fit principle).
    let mut score = post_residual as f64;

    // 2. Lookahead optimization: If a future item exists, prefer bins that can accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can fit the next item (synergy).
            score -= 45.0;
        } else if post_residual > 0 && post_residual < 20 {
            // Penalize small "fragment" residuals that are too small for almost anything.
            score += 25.0;
        }
    }

    // 3. Global state awareness:
    // If this is a new bin (bin_residual == bin_capacity), penalize it based on how many
    // bins are already open to discourage fragmentation, but allow it if current bins
    // are highly inefficient (low mean_residual).
    if bin_residual == bin_capacity {
        score += 30.0 + (open_bins_count as f64 * 2.0);
        if mean_residual < 15.0 && open_bins_count > 2 {
            score -= 20.0;
        }
    }

    // 4. Scarcity handling:
    // If only one bin can fit the current item, prioritize it strongly to avoid new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 5. Dynamic horizon:
    // As the stream progresses, prioritize tighter packing to reduce the tail end bin count.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let capacity = bin_capacity as f64;

    // Base score is the remaining space (Best Fit principle).
    // We penalize larger post_residuals to keep bins tightly packed.
    let mut score = post;

    // Non-linear penalty for leaving "dead space" that is too small for common items.
    // As the stream progresses, we become more conservative about wasting space.
    let waste_penalty = (1.0 - (post / capacity)) * (1.0 + progress * 5.0);
    score += waste_penalty * 10.0;

    // Lookahead coupling: If a large next_item_size is coming, penalize bins that 
    // leave insufficient space for it (post_residual < next_item_size).
    if next_item_size > 0 {
        let lookahead_pressure = (next_item_size as f64 / capacity).powf(2.0);
        if post_residual < next_item_size {
            score += lookahead_pressure * 50.0;
        }
    }

    // Dynamic thresholding: If we are near the end of the stream, prioritize 
    // filling existing bins over opening new ones.
    if bin_residual == bin_capacity {
        // This is a new bin candidate. 
        // Penalize opening a new bin heavily if fitting_bins_count is high.
        score += (fitting_bins_count as f64 * 20.0) * (1.0 - progress * 0.5);
    } else {
        // Reward bins that bring the mean_residual closer to the item_size 
        // to maintain uniform distribution of bin states.
        let deviation = (post - mean_residual).abs();
        score -= deviation * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: Penalize leaving large gaps
    // The smaller the post_residual, the better (Best Fit).
    // We heavily penalize post_residuals that are too small to fit common items (10-20)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead / Harmonic Coupling:
    // If we have a next_item_size, we want to ensure the post_residual can accommodate it.
    // If next_item_size fits in the post_residual, reward the placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 40.0;
        } else {
            // If it doesn't fit, we penalize the bin based on the "waste" ratio
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // 3. New Bin Thresholding:
    // If this is a new bin (bin_residual == bin_capacity), only pick it if 
    // the existing bins are "crowded" (low mean_residual) or if no bins fit well.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 10.0; // Forced to open new bin
        } else {
            // Penalize opening a new bin if we have plenty of open bins
            score += (open_bins_count as f64) * 5.0;
            // Penalize if mean_residual is high (we have space elsewhere)
            score += mean_residual * 0.2;
        }
    }

    // 4. Harmonic Alignment:
    // Favor bins that result in residuals divisible by 10 or 25 (common sizes)
    if post_residual % 10 == 0 {
        score -= 5.0;
    }
    if post_residual % 25 == 0 {
        score -= 8.0;
    }

    // 5. Progression scaling:
    // As we approach the end of the stream, prioritize closing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Avoidance: Penalize gaps that are too small for common items (< 10)
    // or gaps that leave awkward mid-range space (e.g., 1-9 is very hard to fill).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 1.0);
    }

    // 2. Lookahead Integration: If the next item can fit perfectly or near-perfectly
    // in the resulting residual, reward this bin choice.
    if next_item_size > 0 && post_residual >= next_item_size {
        let diff = (post_residual - next_item_size) as f64;
        if diff == 0.0 {
            score -= 40.0; // Perfect fit bonus
        } else if diff < 5.0 {
            score -= 20.0; // Near-perfect fit bonus
        }
    }

    // 3. Open Bins Pressure: Penalize opening new bins when many are already active.
    // If this is a new bin (bin_residual == bin_capacity), increase cost based on open_bins_count.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 5.0;

        // If there are other bins that could fit the item, heavily penalize opening a new one
        // unless the mean residual is already quite low.
        if fitting_bins_count > 0 {
            score += 30.0;
        }
    }

    // 4. Global Efficiency: If the resulting post_residual is significantly better 
    // than the current mean, provide a slight incentive.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // 5. Progression awareness: As we approach the end of the stream, 
    // prioritize closing bins (lower post_residual) over keeping them open.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large residual space.
    // If we create a tiny residual (< 10), we reward it (Best-Fit principle).
    if post_residual < 10 {
        score -= 50.0;
    }

    // 2. Lookahead Matching: If the next item fits into the post_residual,
    // strongly reward this bin to avoid fragmentation.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 120.0;
        // Further reward if the fit is extremely tight for the next item.
        if (post_residual - next_item_size) < 5 {
            score -= 40.0;
        }
    }

    // 3. Mean Residual Calibration: Avoid bins that deviate significantly
    // from the average residual of other bins to maintain uniform packing density.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.5;

    // 4. Scarcity/Fitting Pressure: If this is the only bin that fits the current item,
    // prioritize it heavily to avoid opening a new bin prematurely.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // 5. New Bin Logic: If this is a new bin (bin_residual == bin_capacity),
    // heavily penalize it unless the open bins are all "bad" fits.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 80.0;
        // If we are near the end of the stream, penalize new bins more.
        score += (step_index as f64 / total_items as f64) * 50.0;
    }

    // 6. Avoid "Dead Zone" sizes: If the resulting residual is too small to be useful
    // for common items (e.g., < 10), it's often a waste.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Strategy: Minimize Best-Fit while penalizing small, unusable remainders (fragmentation).
    // If the bin is new, apply a heavy penalty to discourage opening new bins unless necessary.
    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post_residual as f64;

    // 1. Fragmentation Penalty: Penalize remainders that are too small to fit typical future items.
    // If post_residual is between 1 and 9, it is highly likely to be wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead Integration: If the next item fits into the current post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
