    }

    // 3. Global State Balancing: If we have many open bins, penalize opening a new one.
    // If we have few open bins, favor filling the most tight bin (Best-Fit).
    if is_new_bin {
        score += 40.0 + (open_bins_count as f64 * 2.0);
    } else {
        // If this is the only bin that can fit the item, prioritize it strongly.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
    }

    // 4. Dynamic Time Horizon: As the stream progresses, tighten the tolerance for new bins.
    let progress = step_index as f64 / total_items as f64;
    if is_new_bin {
        score += progress * 20.0;
    }

    // 5. Mean Residual Alignment: Avoid bins that deviate significantly from the average fullness.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Penalize creating tiny gaps that are unlikely to accommodate future items
    // We treat post_residual as a potential "dead space" cost.
    // Optimal bins minimize post_residual, but we also want to avoid "fragmentation" 
    // where we leave behind gaps smaller than the average incoming item.
    let fragmentation_penalty = if post_res < 15.0 && post_res > 0.0 {
        (15.0 - post_res) * 5.0
    } else {
        0.0
    };

    // Factor in the lookahead: if the next item fits into the current post_residual,
    // we prioritize this bin heavily (negative bias).
    let lookahead_bonus = if next_item_size > 0 && post_res >= next_item_size as f64 {
        -25.0 * (1.0 - progress)
    } else {
        0.0
    };

    // Normalize open_bins_count influence: as we approach the end of the stream,
    // we should be more conservative about opening new bins.
    let new_bin_penalty = if bin_residual == bin_capacity {
        50.0 * (1.0 + progress)
    } else {
        0.0
    };

    // Non-linear coupling: Favor bins where the post_residual is close to the mean_residual
    // to keep the bin distribution balanced.
    let balance_score = (post_res - mean_residual).abs() * 0.5;

    // Combine factors:
    // 1. post_res (The primary objective: Best Fit)
    // 2. fragmentation_penalty (Avoid small unusable gaps)
    // 3. lookahead_bonus (Greedy lookahead)
    // 4. new_bin_penalty (Control bin count growth)
    // 5. balance_score (Maintain homogeneous bin states)
    let score = post_res + fragmentation_penalty + lookahead_bonus + new_bin_penalty + balance_score;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

