    // Discourage opening a new bin (where bin_residual == bin_capacity) 
    // unless the fit in existing bins is truly abysmal.
    if bin_residual == bin_capacity {
        score += 40.0 + (progress * 20.0);
    }

    // Equilibrium: avoid creating bins that deviate too far from the mean_residual
    // to keep bin utilization balanced.
    score += (post_res - mean_residual).abs() * 0.5;

