        // If there are existing bins that could fit the item, penalize opening a new one.
        if fitting_bins_count > 0 {
            score += 60.0;
        }
    } else {
        // 4. Consolidation: Reward filling bins that are already "fuller" than the mean.
        if (bin_capacity - bin_residual) > mean_residual as u32 {
            score -= 10.0;
        }

        // 5. Critical Constraint: If this is the only bin that can fit the item, prioritize it.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead zones" (residuals too small for common items)
    // Residuals < 10 are often unfillable.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead optimization (2-step matching)
    // If next_item_size fits in the post_residual, reward this bin heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
