    // 4. Global balance
    // If we are opening a new bin (bin_residual == bin_capacity), penalize it 
    // unless the current average residual is already quite low.
    if bin_residual == bin_capacity {
        score += 25.0 + (mean_residual * 0.5);
    }

    // 5. Dynamic scaling based on progression
    // As the stream nears completion, become more conservative (packing tighter).
    let progress = step_index as f64 / total_items as f64;
    score += (progress * 10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Decreasing logic: penalize large residuals after placement.
    // The base score is post_residual, which naturally favors Best-Fit.

    // 2. Penalty for creating "fragmented" small residuals that are unlikely to fit future items.
    // If post_residual is < 10 (the minimum item size), it is likely wasted space.
    if post_residual < 10 && post_residual > 0 {
        score += 50.0;
    }

    // 3. Lookahead integration: adjust score based on the next item.
    // If the next item cannot fit into this post_residual, we penalize the bin.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0;
