    // If we have many open bins, penalize opening a new one.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin is higher if we already have many bins open
        // or if we are deep into the stream and should be consolidating.
        score += (open_bins_count as f64 * 5.0) + (progress * 40.0);
    }

    // 5. Fitting bins count logic:
    // If this is the ONLY bin that can fit the item, we should take it regardless 
    // of the residual to avoid opening a new bin prematurely.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // 6. Mean residual balancing:
    // Favor bins that align with the current average density of active bins.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
