    }

    // 4. New Bin Threshold: Discourage opening new bins unless the fit is very poor.
    // If bin_residual == bin_capacity, we are evaluating a new bin.
    if bin_residual == bin_capacity {
        // Only pick a new bin if the average residual of existing bins is already very small
        // or if we are forced to (handled by the relative scores).
        score += mean_residual * 0.8;
        score += (open_bins_count as f64 * 2.0);
