        // Penalty for opening a new bin increases as the stream progresses
        score += 15.0 + (progress * 40.0);
    }

    // 6. Balance the load: Penalize bins that deviate significantly from the mean residual
    // to keep remaining space distributed evenly across all open bins.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: If the post_residual is small (1..9), it creates a "dead zone" 
    // where most items (min 10) cannot fit. Penalize this heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64);
    }

    // 2. Lookahead Synergy: If the next item fits into the current post_residual, 
    // reward this bin to prioritize packing pairs.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 0.8;
    }

    // 3. Open Bin Pressure: As we progress through the stream, penalize opening new bins 
    // (where bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 2.5;
        // Discourage opening a new bin if other bins can still fit the item
        if fitting_bins_count > 0 {
            score += 40.0;
        }
    }

    // 4. Tightness bias: Prefer bins that are already "tight" (low mean_residual) 
    // to consolidate space, but only if they can accommodate the current item well.
    score += (mean_residual * 0.2);

    // 5. Progression scaling: As the stream nears the end, prioritize finishing 
    // existing bins over starting new ones to reduce residual waste.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals to favor tight packing.
    // However, if fitting_bins_count is 1, we are at a "last chance" state, 
    // so we reduce the penalty to prevent opening a new bin too aggressively.
    if fitting_bins_count > 0 {
        score += (post_residual as f64).powf(1.5) / (fitting_bins_count as f64 + 1.0);
    }

    // 2. Lookahead Synergy: If the next item fits perfectly into the post_residual, 
    // reward this bin heavily (negative score contribution).
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        score -= 50.0 / (1.0 + diff);

        // Penalize if the next item cannot fit in the remaining space
        if next_item_size > post_residual {
            score += 15.0;
        }
    }

    // 3. Global Efficiency: If this bin is empty (new bin candidate), 
    // calculate a cost based on the mean residual. If we have many open bins 
    // with high residuals, opening a new bin is penalized.
    if bin_residual == bin_capacity {
        score += 25.0 + (mean_residual * 0.5);
        // If we are near the end of the stream, discourage opening new bins.
        let progress = step_index as f64 / total_items as f64;
        score += progress * 20.0;
    } else {
        // Favor bins that are closer to the mean residual to keep distribution uniform
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Strategy: Best-Fit Decreasing logic augmented with lookahead and bin utilization optimization.
    // We aim to minimize the post_residual (Best Fit), but penalize creating "fragmented" bins
    // that are too small to fit future items.

    let mut score = post_residual as f64;

    // 1. Penalize creating a new bin if an existing one can fit the item
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 40.0;
    }

    // 2. Lookahead: If the current placement leaves a residual that is too small for 
    // the next item, penalize it to encourage leaving room for the next known item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // 3. Efficiency: If this is the only bin that can fit the item, prioritize it 
    // heavily to avoid wasting the current bin's potential.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // 4. Global State: If the average residual is high, we are currently "loose".
    // We penalize bins that increase the average residual further to maintain tight packing.
    if mean_residual > 30.0 {
        score += (post_residual as f64 - mean_residual) * 0.5;
    }

    // 5. Dynamic Time Horizon: As the stream nears completion, prioritize closing bins
    // by favoring lower post_residuals more aggressively.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (1.0 - progress) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
