        score += 150.0 * (1.0 + progress);
    }

    // Coupling: If the residual is close to the mean, it's a "stable" bin, reward it
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    // Scale by progression to favor tighter packing early on
    score *= 1.0 + (progress * 0.5);

