    }

    // 4. Threshold Logic for New Bins:
    // If this is a new bin (bin_residual == bin_capacity), penalize it unless fitting_bins_count is low.
    // This prevents fragmenting capacity when a valid fit exists.
    if bin_residual == bin_capacity {
        score += 40.0;
        // If we are at the end of the stream, be more conservative about opening new bins.
        let progress = step_index as f64 / total_items as f64;
        score += progress * 30.0;
    }

    // 5. Mean residual balancing:
    // If the current bin's residual is significantly larger than the mean, 
    // it's an inefficient bin; penalize using it to force consolidation.
    if bin_residual as f64 > mean_residual + 10.0 {
        score += 20.0;
    }

    // 6. Last Chance Heuristic:
    // If fitting_bins_count is 1, this is the only bin that can hold the item.
    // Reduce the score to ensure we don't open a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
