    // 2. Open bins pressure: If we have many open bins, we should prioritize filling existing ones
    // to keep the bin count low. If we have very few, we can be more selective.
    score += (open_bins_count as f64) * 2.5;

    // 3. Lookahead synergy: If the next item fits into the post_residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
