    // 5. New Bin penalty: Discourage opening a new bin unless the fit is perfect or we are 
    // forced to (handled by the caller if this score is the lowest).
    if bin_residual == bin_capacity {
        // Only consider a new bin if we are constrained or if the item is large.
        score += 35.0 + (item_size as f64 * 0.2);
    }

    // 6. Mean residual balancing: Prefer bins that are closer to the current mean occupancy
    // to keep the "wastage" distributed somewhat evenly across open bins.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals to keep bins packed.
    // We favor bins that leave little space remaining.
    score += post_residual as f64 * 0.5;

    // 2. Lookahead Synergy: If post_residual can accommodate the next item, 
