    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 2.5;
        // Further reward if it creates a near-perfect fit for the next item.
        let waste_after_next = (post_residual - next_item_size) as f64;
        score += waste_after_next * 0.2;
    }

    // 3. Fragmentation Control: Discourage creating many bins with small residuals
    // that are too small for future items (below 10).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // 4. Global Load Balancing: Avoid creating new bins if existing bins are already 
    // performing well (mean_residual).
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            score += 45.0 + (mean_residual * 0.5);
        }
    } else {
        // Reward bins that stay close to the current global average to maintain uniformity.
        let diff_from_mean = (post_residual as f64 - mean_residual).abs();
        score += diff_from_mean * 0.1;
    }

    // 5. Urgency Constraint: If this is the only bin that fits the item, 
    // prioritize it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 6. Progression Scaling: As the stream nears completion, become more aggressive 
    // in packing to avoid leaving orphan items.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Current progress factor [0, 1]
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base score: prioritize tighter fits (smaller post_residual)
    let mut score = post_residual as f64;

    // Penalty for opening a new bin: only open if the fit in existing bins is truly abysmal
    if bin_residual == bin_capacity {
        // High barrier for new bins: only open if we have many open bins already or 
        // if the item size is very large (likely to be hard to place later)
        score += 25.0 + (item_size as f64 * 0.5) + (open_bins_count as f64 * 2.0);
    } else {
        // Lookahead heuristic: if a future item exists, prefer bins that leave 
        // space for the next item, or minimize the "wasted" space that is too small for common items.
        if next_item_size > 0 {
            if post_residual < next_item_size {
                // This bin will likely be unable to fit the next item; penalize this bin
                // unless the residual is very small (near perfect fit)
                score += 15.0 * (1.0 - (post_residual as f64 / item_size as f64));
            }
        }

        // Global state consideration:
        // If we are late in the stream, prioritize closing bins (minimizing mean_residual)
        // If we have many open bins, penalize bins that leave a "medium" amount of space (fragmentation)
        if open_bins_count > 5 {
            if post_residual > 15 && post_residual < 30 {
                score += 10.0;
            }
        }

        // Dynamic horizon: as we approach the end, be more aggressive about packing tightly
        score -= progress * (bin_capacity - post_residual) as f64 * 0.1;
    }

    // Fitting count pressure: if this is the only bin that can fit the item, 
    // heavily reward it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the residual space after placement (Best Fit principle)
    let mut score = post;

    // Penalty for opening a new bin: if it's the only option or if we are early in the stream, 
    // we discourage premature new bin allocation.
    if bin_residual == bin_capacity {
        score += 45.0 * (1.0 - progress).powf(0.5);
    }

    // Interaction term: If the remaining space is small, it creates "dead space" that is hard to fill.
    // We penalize very small residuals (e.g., < 10) unless it's a perfect fit (post == 0).
    if post > 0.0 && post < 12.0 {
        score += (15.0 - post).powf(1.5);
    }

    // Lookahead logic: If the next item is large, favor bins that leave enough room for it.
    if next_item_size > 0 {
        let fit_margin = post - (next_item_size as f64);
        if fit_margin < 0.0 {
            // Penalize bins that cannot fit the next item if this is the only fitting bin
            if fitting_bins_count == 1 {
                score += 20.0;
            }
        } else {
            // Reward bins that create a "tight fit" for the next item to keep residuals low
            score -= (1.0 / (fit_margin + 1.0)) * 5.0;
        }
    }

    // Global state scaling: As the stream progresses, prioritize closing bins (lower mean_residual)
    // to consolidate space.
    score += (mean_residual / (bin_capacity as f64)) * 10.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base penalty for creating small, unusable gaps (The "Fragment Trap")
    // If post_residual is in (0, 10), it is highly likely to be wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Harmonic Lookahead: prioritize bins that can accommodate the next item.
    // If next_item_size fits in the post_residual, lower the score.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
