    if bin_residual == bin_capacity {
        // Penalty for opening a new bin: scale by how many bins are already open
        score += (open_bins_count as f64) * 2.5;
        // If we are late in the stream, be more conservative about opening new bins
        score += (step_index as f64 / total_items as f64) * 20.0;
    } else {
        // If it's a tight fit (residual close to item_size), reward it (Best Fit principle)
        if post_residual < 15 {
            score -= 15.0;
        }
    }

    // 4. Global state adjustment:
    // If the current bin's residual is significantly better than the global mean, 
    // it's a "good" bin. We want to preserve it if possible.
    if (bin_residual as f64) < mean_residual {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

