        // Reward bins that are closer to the mean residual to keep distribution uniform.
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score -= deviation * 0.1;

        // If this is the last fitting bin, slightly reward placing here to avoid opening a new one.
        if fitting_bins_count == 1 {
            score -= 5.0;
        }
    }

    // Non-linear coupling: dampen the score by the progress to ensure stability in early phases.
    score * (1.0 + (progress * 0.2))
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
