        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        score -= (100.0 - diff) * 0.8;
    }

    // 3. New bin penalty: Heavily penalize opening a new bin unless the current 
    // configuration is extremely poor.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            score += 150.0;
        }
    }

    // 4. Fitting constraints: If this is the last bin that can fit the item, 
    // prioritize using it to avoid unnecessary new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 5. Global efficiency: If the residual is significantly smaller than the 
    // current mean, we are creating a tighter-than-average bin. Reward this.
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 0.5;
    }

    // 6. Final normalization: Favor closing bins (post_residual == 0).
    if post_residual == 0 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
