            score += 40.0 * (1.0 - progress);
        }
    }

    // Dynamic preference: As we approach the end of the stream, prioritize 
    // filling bins tightly to avoid trailing empty bins.
    let tightness_factor = (1.0 - progress) * 15.0;
    score -= (bin_capacity as f64 - post) * tightness_factor / 100.0;

    // Favor using existing bins over opening new ones, weighted by the number of open bins.
    // If bin_residual == bin_capacity, this is a new bin candidate.
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin unless it's the only option or the stream is early.
        score += 50.0 + (open_bins_count as f64 * 5.0) + (progress * 20.0);
    } else {
