        // If this is the only bin that can fit the item, give it a significant priority boost.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
    }

    // Non-linear coupling with mean_residual to maintain balance across all open bins.
    let deviation = (post - mean_residual).abs();
    score += deviation * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

