    if bin_residual == bin_capacity {
        // Only open a new bin if the current open bins are very full (mean_residual is low).
        // If mean_residual is high, we should use existing bins instead of opening a new one.
        score += (mean_residual * 2.0) + (open_bins_count as f64 * 5.0);
