    let harmonic_fit = (post_residual as f64 % 25.0).abs();
    score += harmonic_fit * 0.5;

    // Lookahead logic: if next_item_size is large, penalize small residuals that would force new bins
    if next_item_size > 0 && post_residual < next_item_size {
