    // When residual == capacity, we are evaluating a new bin. 
    // We only open a new bin if the current existing bins have very poor fit prospects.
    if bin_residual == bin_capacity {
        // High penalty for opening new bins, but it decreases as we get closer to the end of the stream
        // to ensure we don't end up with a high residual count at the very end.
        score += 35.0 + (progress * 15.0);

        // If the mean residual is already high, we should try to fit in existing bins instead.
        score += mean_residual * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize new bin creation (bin_residual == capacity) unless necessary
    // We scale the penalty by the current progress to become more conservative as the stream ends
    let new_bin_penalty = if bin_residual == bin_capacity {
        (100.0 * (1.0 + progress)) + (open_bins_count as f64 * 5.0)
    } else {
        0.0
    };

    // Reward placements that leave a residual close to the expected future item size
    // We use a quadratic penalty for the difference between post_residual and mean_residual
    let tightness_bonus = (post - mean_residual).powi(2) * 0.1;

    // Lookahead logic: if next_item_size is large, avoid creating a post_residual that is too small
    // to fit the next item (effectively creating dead space).
    let lookahead_penalty = if next_item_size > 0 && post < next_item_size as f64 {
        (next_item_size as f64 - post) * 2.5
    } else {
        0.0
    };

    // If this is the last chance to fit the item in an existing bin, reduce score to prioritize it
    let desperation_bonus = if fitting_bins_count == 1 && bin_residual != bin_capacity {
        -50.0
    } else {
        0.0
    };

    // Combine factors:
    // Base score is post_residual (Best Fit principle).
    // We minimize this, so smaller post_residual is generally better, 
    // but modified by the penalties and bonuses above.
    let mut score = post + new_bin_penalty + tightness_bonus + lookahead_penalty + desperation_bonus;

    // Dampen the score based on total open bins to avoid fragmentation
    score += (open_bins_count as f64).powf(1.2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Heavily penalize residuals that are small but unusable 
    // for common item sizes (e.g., leaving 5-9 space is often worse than 0).
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    }

    // 2. Lookahead Logic: If next_item_size fits in the post_residual, reward this bin placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
    }

    // 3. Fitting Scarcity: If this is the only bin that can fit the current item, 
    // prioritize it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // 4. New Bin Threshold: If evaluating an empty bin (bin_residual == bin_capacity),
    // only choose it if the current density of open bins is very low.
    if bin_residual == bin_capacity {
        // Only open a new bin if we have few bins or the items are significantly large
        // compared to the mean residual of current bins.
        if open_bins_count > 0 && mean_residual > 20.0 {
            score += 25.0;
        } else {
            score += 15.0;
        }
    }

    // 5. Modulo Alignment: Favor residuals that align with common harmonic fractions 
    // of the bin capacity (e.g., 0, 25, 33, 50).
    let rem = post_residual % 25;
    if rem == 0 {
        score -= 10.0;
    }

    // 6. Stream Progression: As we approach the end of the stream, 
    // tighten the tolerance for residuals to maximize packing density.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: Penalize post_residuals that are too small to fit future items.
    // If post_residual is in the range (0, 10), it is highly likely to be "dead space"
    // since the minimum item size is typically 10.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. Lookahead Synergy: If the next item fits in the current post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
