    // 5. Scarcity Constraint: If this is the last fitting bin, slightly reward it
    // to prevent unnecessary new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // 6. High-density incentive: Favor bins that are already well-utilized.
    score -= (bin_capacity - bin_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual, but heavily penalize extremely small gaps (1-4)
    // which are likely to remain stranded for the duration of the stream.
    if post_residual > 0 && post_residual <= 4 {
        score += 25.0;
    }

    // 2. Lookahead Integration: If the next item fits into the current post_residual, 
    // prioritize this bin to maximize packing density (Best-Fit-Lookahead).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
    }

    // 3. Global State: If we have many open bins, prioritize filling existing ones 
    // (penalize opening new bins). If open_bins_count is low, we are more flexible.
    let fill_ratio = 1.0 - (mean_residual / bin_capacity as f64);
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin: scales with the current density of open bins.
        score += 20.0 + (fill_ratio * 30.0);
    }

    // 4. Scarcity Logic: If this is the only bin that can fit the item, 
    // we must take it unless it results in a terrible gap.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // 5. Dynamic Time Horizon: As we reach the end of the stream, 
    // prioritize closing bins (lower post_residual) to reduce wasted trailing capacity.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the remaining capacity. Lower is better (Best Fit).
    let mut score = post_res;

    // Penalty for creating "dead space": if post_residual is small but > 0, 
    // it prevents larger items from fitting later. We penalize values 
    // that are too small to be useful (e.g., < 10) but not zero.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - progress);
    }

    // Lookahead: If the next item is large, prioritize bins that can accommodate it.
    // If post_residual is smaller than the next_item_size, we penalize the bin.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 15.0 * (1.0 - progress);
        }
    }

    // New bin bias: We only open a new bin if the current fit is poor.
    // If bin_residual == bin_capacity, this is a new bin candidate.
    if bin_residual == bin_capacity {
        // Only open a new bin if we are early in the stream or if existing bins are very full.
        // We add a cost that decreases as the stream progresses, making it easier to 
        // start new bins early to "prime" the packing density.
        score += 20.0 + (10.0 * progress);

        // If we have many open bins, penalize opening a new one to encourage consolidation.
        score += (open_bins_count as f64) * 5.0;
    } else {
        // If this is the last chance to fit the item in an existing bin, reward it strongly.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
    }

    // Coupling: Use mean_residual to penalize bins that are significantly 
    // tighter than the global average to promote uniform filling.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.5 * dev * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Heuristic #786: Harmonic-Residual Balancing
    // We prioritize bins that leave a post_residual that is a "harmonic multiple" of the next item.
    // If post_residual is small (e.g., < 10), we penalize it heavily to avoid "dead-space" fragmentation.
    // If we have a lookahead (next_item_size), we reward bins that perfectly accommodate it.

    let mut score = post_residual as f64;

    // 1. Fragmentation Penalty: Heavily penalize tiny slivers of space that cannot fit the smallest possible item (assumed ~10)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. Lookahead Synergy: If the next item fits perfectly into the post_residual, apply a massive discount
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual < (next_item_size + 15) {
            // Reward bins that have just enough room for the next item plus a small buffer
            score -= 15.0;
        }
    }

    // 3. Harmonic Packing: Favor bins where the post_residual is a multiple of 20 (harmonic class)
    // This tends to group items into bins that leave "clean" remainders for future items.
    if post_residual % 20 == 0 {
        score -= 10.0;
    }

    // 4. New Bin Thresholding: 
    // If this is a new bin (bin_residual == bin_capacity), penalize it unless fitting_bins_count is 0.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 60.0; // Strong deterrent against unnecessary new bins
        } else {
            score -= 20.0; // Bias toward opening a new bin if no other choice exists
        }
    }

    // 5. Global Density Balancing: 
    // If the bin's residual is significantly better than the mean, prefer it.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
