    let mut score = post_residual as f64;

    // Penalty for creating "dead space": residuals that are too small to fit typical future items
    // (based on the assumption that items are generally >= 10)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (1.0 - progress);
    }

    // Lookahead logic: if next_item fits in the current post_residual, reward this bin
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 * (1.0 - progress);
    }

    // Dynamic threshold for opening new bins:
    // Only open a new bin if the current mean residual is already quite low,
    // or if we are at the very end of the stream.
    if is_new_bin {
        if fitting_bins_count > 0 {
            // Apply a heavy penalty for opening a new bin if an existing bin could fit the item
            score += 50.0 + (mean_residual * 0.5) + (progress * 20.0);
        } else {
            // If no other bin fits, this is a necessary new bin
            score = 0.0;
        }
    } else {
        // Encourage filling bins that are already "half-full" to keep open_bins_count low
        let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= fill_ratio * 10.0;
    }

    // Global state awareness: if we have many bins open, prioritize closing existing ones
    // by penalizing bins that leave very large residuals (fragmentation)
    score += (open_bins_count as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let capacity = bin_capacity as f64;

    // Penalize opening new bins early in the stream, but allow it more freely as we approach the end
    let open_bin_penalty = if bin_residual == bin_capacity {
        (1.0 - progress) * 50.0 + (fitting_bins_count as f64 * 10.0)
    } else {
        0.0
    };

    // Calculate a "tightness" score: prefer bins that leave little space (Best Fit)
    // but weigh it against the lookahead to avoid stranding the next item.
    let mut score = post;

    // Non-linear coupling: penalize leaving small, unusable gaps (1..10) 
    // especially as the stream progresses and the likelihood of fitting small items decreases.
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * (1.0 + progress * 5.0);
    }

    // Lookahead logic: if the next item is large, penalize bins that cannot fit it 
    // after the current item is placed.
    if next_item_size > 0 {
        if post < next_item_size as f64 {
            // Significant penalty for stranding a large item
            score += (next_item_size as f64 - post) * 1.5;
        }
    }

    // Balance against the mean residual: favor bins that keep the overall cluster 
    // density consistent with the current average.
    let deviation = (post - mean_residual).abs();
    score += deviation * 0.5;

    // Apply the new-bin penalty
    score += open_bin_penalty;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

