    // If post_residual is small but > 0, it often creates "dead space" that cannot fit 
    // items > post_residual. We penalize this unless it's a perfect fit (0).
    if post_residual > 0 {
        score += (bin_capacity as f64 - post_residual as f64) * 0.15;
    }

    // 2. Lookahead Logic: If the next item can fit in the current post_residual, 
    // prioritize this bin heavily to preserve packing density.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 1.5;
    }

    // 3. New Bin Thresholding: Discourage opening new bins unless the fit is poor.
    // If this is an empty bin (bin_residual == bin_capacity), apply a heavy penalty
    // proportional to the number of existing bins to force consolidation.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 45.0 + (open_bins_count as f64 * 0.5);
    }

    // 4. Harmonic Alignment: Favor bins where the residual aligns with the mean_residual
    // to keep the "temperature" of the bins consistent.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    // 5. Last Chance Heuristic: If only one bin can fit the current item, 
    // it is usually better to use it than to open a new bin, unless the fit is atrocious.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 6. Progression Scaling: As the stream nears completion, become more aggressive 
    // about filling bins tightly to avoid trailing single-item bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

