pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize creating tiny, unusable gaps (1..10) which are hard to fill later.
    // We use a sigmoid-like penalty for post_residual < 10.
    let fragmentation_penalty = if post < 10.0 && post > 0.0 {
        (10.0 - post) * 5.0
    } else {
        0.0
    };

    // Reward bins that have residuals closer to the next_item_size to maintain high density.
    // If next_item_size is 0, we favor keeping residual as small as possible.
    let lookahead_alignment = if next_item_size > 0 {
        (post - next_item_size as f64).abs() * 0.5
    } else {
        post * 0.2
    };

    // Favor bins that align with the global mean_residual to keep bin states uniform.
    let uniformity_bonus = (post - mean_residual).abs() * 0.3;

    // As the stream progresses, become increasingly conservative about opening new bins.
    // If bin_residual == bin_capacity, we are evaluating a new bin.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
