pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the post-placement residual. Smaller is generally better (Best Fit principle).
    let mut score = post_residual as f64;

    // Penalty for leaving "unusable" small gaps (fragmentation).
    // Gaps < 10 are often impossible to fill given the input range.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (1.0 - progress);
