        // If this bin is the last chance for the current item, prioritize it.
        if fitting_bins_count == 1 {
            score -= 40.0;
        }

        // Reward bins that maintain a residual close to the global mean to keep packing uniform.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
