    score += (mean_residual - post_res) * 10.0;

    // If this is the only bin that can fit the item, prioritize it to avoid wasting a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 1000.0;
    }

    score
