    // We favor bins that result in smaller post_residual values to pack tightly.
    score += post_residual as f64 * 0.5;

    // 2. Lookahead Synergy: If next_item_size fits in the post_residual, reward this placement
    if next_item_size > 0 && next_item_size <= post_residual {
