    // 5. Progress-Aware Scaling:
    // As we approach the end of the stream, tighten the requirements to avoid leaving bins half-empty.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score += (post_residual as f64) * 2.0;
    }

    // 6. Harmonic Class Logic:
    // Favor placing items that leave residuals which are multiples of common item sizes.
    if post_residual % 25 == 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
