    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.5);

    // Lookahead: If next_item_size is large, penalize current bin choices that leave 
    // too little space for the next item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 2.0;
    }

    // Pressure: Penalize opening new bins when many bins are already open,
    // but reward opening a new bin if the current 'fitting' option leaves a 'dead' gap.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Only open a new bin if the current open bins are already quite full
        // or if we have too many open bins (fragmentation).
        score += (open_bins_count as f64 * 5.0) + (mean_residual * 0.5);
    } else {
        // If it's an existing bin, reward configurations that keep the mean_residual
        // balanced, preventing one bin from becoming an outlier.
        score += (post_residual as f64 - mean_residual).abs() * 0.2;
    }

    // Final constraint: If this is the only bin that fits the item, make it highly attractive.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. If this is a new bin, apply a threshold penalty to prevent unnecessary bin creation
    // unless the item is very large or the mean residual is already quite low.
    if bin_residual == bin_capacity {
        // Penalty is higher if we have many bins already open or if the item is small.
        score += 40.0 + (open_bins_count as f64 * 2.0) + (item_size as f64 * 0.5);
    } else {
        // 2. Best-Fit logic: Penalize large post_residuals (wasted space)
        score += post_residual as f64 * 1.5;

        // 3. Lookahead Matching (The core heuristic):
        // If the current bin can perfectly fit the next item after this one, reward it.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= (next_item_size as f64) * 2.5;

            // If it creates a near-perfect fit (residual < 5), give a massive bonus.
            if post_residual - next_item_size < 5 {
                score -= 50.0;
