        // 4. Fitting constraints:
        // If this is the only bin that fits, we are forced to take it, but we penalize
        // if it leaves a "sliver" of space (e.g., 1-9) that is hard to fill.
        if fitting_bins_count == 1 && post_residual > 0 && post_residual < 10 {
            score += 25.0;
        }

        // 5. Global state normalization:
        // If the bin's residual is significantly lower than the global mean, 
        // we prioritize it to keep the mean space usage high.
        if (post_residual as f64) < mean_residual {
            score -= 10.0;
        }
    }

    // 6. Progress factor: As we approach the end of the stream, be more conservative
    // about opening new bins.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
