    // We heavily penalize values between 1 and 9 as they are difficult to fill
    if post_residual > 0 && post_residual < 10 {
        score += 45.0 * (1.0 + progress);
    }

    // Lookahead logic: If the next item can fit in the post_residual, reward this bin
    if next_item_size > 0 && post_residual >= next_item_size {
