            score += 35.0 + (mean_residual * 0.5);
        }
    } else {
        // Encourage using bins that are already partially filled to increase density
        score -= (bin_capacity - bin_residual) as f64 * 0.1;

        // If this is the only bin that can fit the item, prioritize it
        if fitting_bins_count == 1 {
            score -= 50.0;
        }
    }

    // Adjust for the end of the stream: stop being conservative
    if progress > 0.95 {
        score -= (post_residual as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
