    // Non-linear coupling: Exponential decay towards zero residual
    score -= (100.0 - post).exp() * 0.01;

    // Lookahead: If next_item_size is large, avoid leaving a small post_residual 
    // that cannot accommodate the upcoming item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
