        score += (1.0 - progress) * 50.0 + (open_bins_count as f64 * 2.0);
    } else {
        // Reward bins that keep the mean residual balanced
        score += (post - mean_residual).abs() * 0.5;
    }

    // Critical constraint: If this is the only bin that fits the item, 
    // prioritize it heavily to avoid unnecessary new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals (wasted space)
    // 2. Harmonic Class Logic: If post_residual is small, it's often a "tight fit" (good).
    //    If post_residual is close to a multiple of item_size, it's a "harmonic fit" (good).
    let harmonic_penalty = if item_size > 0 {
        (post_residual % item_size) as f64
    } else {
        0.0
    };
    score += harmonic_penalty * 0.5;

    // 3. Lookahead Logic: If the next item fits into the current post_residual, reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 1.5;
    }

    // 4. Strategic New Bin Threshold:
    // If bin_residual == bin_capacity, we are evaluating a new bin.
    // Penalize opening a new bin unless the existing bins are "crowded" (low mean_residual).
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            // If mean_residual is high, we have plenty of space in existing bins; don't open new ones.
            score += mean_residual * 2.0;
        }
        // Heavily penalize opening a new bin if other bins still have space.
        score += 25.0; 
    } else {
        // 5. Fitting Constraint: If this is the ONLY bin that fits, prioritize it.
        if fitting_bins_count == 1 {
            score -= 50.0;
        }
    }

    // 6. Progression Scaling: As the stream nears the end, be more aggressive with packing.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

