        }
    }

    // 5. Global Efficiency: If the current bin is "better" than the average residual, 
    // reward it to keep the average bin usage consistent.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // 6. Final stage progression: Tighten constraints as we approach the end of the stream.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
