    }

    // 5. Avoid "fragmentation traps": Penalize residual spaces that are too small to be useful
    // (e.g., < 10, since item sizes are >= 10).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the remaining space (Best Fit principle).
    let mut score = post;

    // Penalty for creating "dead zones" (small residuals that are hard to fill).
    // We penalize residuals in the 1-9 range heavily, as they are unlikely to fit future items.
    if post > 0.0 && post < 10.0 {
        score += 50.0 / (post + 1.0);
    }

    // Dynamic Lookahead: If the next item is large, favor bins that leave enough space for it.
    if next_item_size > 0 {
        if post < next_item_size as f64 {
            score += 40.0 * (1.0 - progress);
        }
    }

    // Global Efficiency: Penalize opening new bins as the stream progresses.
    // The cost of a new bin increases as we approach the end of the stream.
    if bin_residual == bin_capacity {
        score += 25.0 + (35.0 * progress);
    }

    // Tightness coupling: Favor bins that are near the mean residual to keep bin levels uniform.
    // This reduces the variance of open bins, keeping more capacity flexible.
    let residual_diff = (bin_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.15;

    // Last chance heuristic: If only one bin can fit the item, prioritize it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Non-linear scaling: Penalize bins that leave very large gaps early in the stream.
    score += (post.powf(1.5)) * 0.02 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize smaller post_residuals to push towards tightest fit (Classic BFD logic)
    // We weight this by the bin_capacity to normalize.
    score += (post_residual as f64).powf(1.5);

    // 2. Harmonic Class Logic: Favor residuals that leave space for common item size multiples (e.g., 20, 25, 33, 50).
    // We reward post_residuals that are multiples of 20, as they are highly flexible for future items.
    if post_residual > 0 && post_residual % 20 == 0 {
        score -= 15.0;
    }

    // 3. Lookahead Synergy: If the next item fits into the current post_residual, reward this bin heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 45.0;
        // Further refine: reward if the resulting space is near zero (perfect pair)
        if (post_residual - next_item_size) < 10 {
            score -= 20.0;
        }
    }

    // 4. Dead Space Avoidance: If post_residual is too small to fit any likely future items (< 10), 
    // it's "dead space". Penalize this unless it's a perfect fit (0).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 5. New Bin Threshold: If this is an empty bin (new bin candidate),
    // only accept it if the cost of opening a new bin is lower than the penalty of the current fit.
    if bin_residual == bin_capacity {
        // Base cost for opening a new bin is high to encourage filling existing bins.
        score = 60.0 + (mean_residual * 0.5);

        // If we are at the end of the stream, prioritize closing bins rather than opening new ones.
        let progress = step_index as f64 / total_items as f64;
        score += progress * 40.0;
    }

    // 6. Crowding Penalty: If many bins are open, push to fill the ones with higher residuals first.
    if open_bins_count > 5 {
        score -= (bin_residual as f64) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: If post_residual is in the "unusable" range (1-9),
    // we heavily penalize it because items are >= 10.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. Lookahead Synergy: If the next item can fit in the remaining space,
    // we reward this bin to keep the next item packed efficiently.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
    }

    // 3. Open Bins Pressure: Penalize opening a new bin if we have many bins already.
    // If this is a new bin (bin_residual == bin_capacity), increase its cost
    // proportional to the number of bins currently open to discourage fragmentation.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 5.0;
    }

    // 4. Fitting Scarcity: If this is the only bin that can fit the item,
    // lower its score significantly to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 5. Global Efficiency: If the post_residual is significantly higher than the 
    // current mean_residual, it suggests this bin is becoming "empty" relative to others,
    // which is generally good for future flexibility.
    if (post_residual as f64) > mean_residual {
        score -= (post_residual as f64 - mean_residual) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalty for opening a new bin if we have fitting alternatives
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 120.0;
    }

    // 2. Best-Fit logic: prioritize bins that become tight (minimize post_residual)
    // We penalize larger post_residuals to favor tight packing.
    score += post_residual as f64 * 0.5;

    // 3. Lookahead Matching (The "Aggressive Match"):
    // If we can perfectly fit the next item into the post_residual, drastically reduce score.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 50.0;
        } else if post_residual > next_item_size {
            // Reward bins that leave exactly enough space for the next item
            score += (post_residual - next_item_size) as f64 * 0.2;
        } else {
            // Penalize if the next item won't fit at all (dead space creation)
            score += 15.0;
        }
    }

    // 4. Mean Residual Balancing:
    // Avoid creating bins that are significantly "emptier" than the current average.
    if (post_residual as f64) > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.3;
    }

    // 5. Urgency: If this is the only bin that can fit the item, prioritize it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 6. Progression factor: As the stream nears the end, prioritize filling existing bins
    // to avoid leaving leftovers in the final stages.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && bin_residual != bin_capacity {
        score -= (1.0 - progress) * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit Penalty: Minimize post_residual, but heavily penalize near-empty bins
    // to encourage consolidation.
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin unless we are forced or it's very early.
        score += 45.0 * (1.0 - progress);
        if fitting_bins_count > 0 {
            score += 30.0;
        }
    }

    // 2. Lookahead Coupling: If the next item is large, prioritize keeping 
    // the current bin residual high enough to fit it if possible.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0; // Reward bins that can accommodate the next item
        } else if post_residual > 0 && post_residual < 20 {
            // Penalize small slivers that are likely to become unusable dead space
            score += 25.0;
        }
    }

    // 3. Global State Balancing: Use mean_residual to avoid fragmenting all bins.
    // If our current bin residual is far below the mean, we are "tightening" the pack.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // 4. Critical Thresholding: If this is the only bin that fits the item,
    // lower the score to ensure we don't prematurely open a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 5. Dynamic Density Adjustment: As the stream nears completion, 
    // become more aggressive about filling existing bins.
    if progress > 0.8 {
        score -= (post_residual as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

