    let mut score = post_res;

    // Penalize creating "dead space" (small residuals that are hard to fill later)
    // We penalize residuals in the range [1, 15] more heavily as they are difficult to fill
    if post_residual > 0 && post_residual < 16 {
        score += (16.0 - post_res) * 5.0;
    }

    // Lookahead logic: if next item is large, favor bins that can accommodate it.
    // If the current post_residual is too small for the next item, penalize this bin.
    if next_item_size > 0 && (post_residual as u32) < next_item_size {
        score += 20.0 * (1.0 - progress);
    }

    // Dynamic thresholding: as we near the end of the stream, prioritize tight packing
    // to minimize the number of bins. 
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 * progress;
    }

    // Interaction between mean_residual and current post_residual:
    // If this bin's post_residual is significantly better (lower) than the mean, 
    // reward it to encourage consolidation.
    if post_res < mean_residual {
        score -= (mean_residual - post_res) * 0.5;
    }

    // Discourage opening new bins early in the stream unless the fit is very poor
    if bin_residual == bin_capacity {
        score += 35.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

