    // 2. Lookahead optimization: If next_item can fit, prioritize bins that leave space for it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Good fit: reward bins that leave exactly enough space for the next item
            score -= (bin_capacity - post_residual) as f64 * 0.5;
        } else {
            // Bad fit: penalize if this choice makes it impossible to fit the next item elsewhere
            score += 20.0;
        }
    }

    // 3. Harmonic class awareness: Prefer filling bins to high density (Best-Fit principle)
    // We use the post_residual as the primary weight.
    // For new bins (bin_residual == bin_capacity), add a significant cost to avoid opening them
    // unless the fit in existing bins is truly abysmal.
    if bin_residual == bin_capacity {
        score += 45.0; 
        // If it's the only option, it will be chosen. If others exist, they will be favored.
    }

    // 4. Global state adjustment: Use mean_residual to balance packing
    // If the mean residual is high, we are under-utilizing bins; be more aggressive with packing.
    if (post_residual as f64) < mean_residual {
        score -= 10.0;
    }

    // 5. Fitting constraint: If this is the last chance for this item, reduce penalty
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // 6. Progression scaling: As we reach the end of the stream, prioritize tight packing
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: Penalize post_residuals that are too small to fit common items (below 10)
    // but large enough to be wasted (e.g., 1-9).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64).sqrt();
    }

    // 2. Lookahead Synergy: If the next item fits into the current post_residual, 
