    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // 5. Global Efficiency: If the current placement leaves the bin near the mean residual 
    // of other bins, it suggests balanced packing.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. If this is a new bin, penalize based on the current mean_residual to prevent 
    // premature opening when existing bins are already under-utilized.
    if bin_residual == bin_capacity {
        score += mean_residual * 1.5;
        // If there are other bins that could fit the item, heavily penalize opening a new one.
        if fitting_bins_count > 0 {
