        // 3. Prefer bins that are already "tight" (low residual) to keep open bin count low.
        // We subtract the post_residual, but weight it such that smaller post_residual is better.
        score += (post_residual as f64).powf(1.1);
    }

    // 4. Normalize based on progression: as we approach the end of the stream, 
    // become more conservative about opening new bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 50.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
