    }

    // 5. Global Efficiency: If current bin residual is significantly above the mean, 
    // it's a "roomy" bin; penalize using it to preserve space for larger future items.
    if (bin_residual as f64) > mean_residual {
        score += (bin_residual as f64 - mean_residual) * 0.5;
    }

