        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Harmonic logic: Reward residuals that align with common multiples to allow future pairings.
    // If post_residual is a multiple of 25 (e.g., 25, 50, 75), it's highly flexible.
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 15.0;
    }

    // 3. Lookahead coupling: If the next item fits into the current post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
        // Further reward if it creates a perfect or near-perfect fit for the next item.
        if (post_residual - next_item_size) < 5 {
            score -= 20.0;
        }
    }

    // 4. Pressure management: If we are near the end of the stream, favor tighter packing.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score += post_residual as f64 * 0.5;
    }

    // 5. New Bin logic: If this is a new bin (bin_residual == bin_capacity), 
    // penalize opening it unless existing bins are very poorly suited.
    if bin_residual == bin_capacity {
        score += 35.0 + (open_bins_count as f64 * 2.0);
        // If there are other bins that could fit the item, discourage opening a new one.
        if fitting_bins_count > 0 {
            score += 40.0;
        }
    }

    // 6. Balance against mean_residual: Avoid bins that deviate too far from the average state.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: Penalize post_residuals that are too small to fit common items (below 10)
    // but large enough to be wasted (e.g., 1-9).
    if post_residual > 0 && post_residual < 10 {
