    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 100.0;
    }

    // 5. Global Mean Residual Alignment: Avoid creating bins that are significantly 
    // less efficient than the current average.
    if (post_residual as f64) > mean_residual + 20.0 {
