        score += (post_residual as f64) * (1.0 + progress);

        // 5. Global state pressure: If mean_residual is high, we are being too wasteful.
        //    Force tighter packing in existing bins.
        if mean_residual > 30.0 {
            score += (mean_residual - 30.0) * 2.0;
        }

        // 6. Penalty for "fragmentation": If we have many open bins, penalize 
        //    placing in a bin that leaves a "useless" gap (e.g., < 10 space).
        if post_residual < 10 && post_residual > 0 {
