        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the post-placement residual. Minimizing this is the Best Fit objective.
    let mut score = post_res;

    // Penalty for creating "slivers" (unusable space < 10) which are often dead weight.
    // We increase score (penalize) if post_residual is small but > 0.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_res) * 5.0;
    }

    // Lookahead logic: if next_item_size is large, favor bins that can accommodate it.
    // If next_item_size is 0, we are at the end, so maximize packing density.
    if next_item_size > 0 {
        let future_fit = post_res - next_item_size as f64;
        if future_fit < 0.0 {
            // Penalize bins that would become "blocked" for the next item.
            score += 20.0 * (1.0 - progress);
        } else {
            // Reward bins that maintain enough space for the next item.
            score -= 15.0 * (1.0 - progress);
        }
    }

    // Dynamic thresholding: as the stream progresses, become more aggressive in packing
    // to minimize the total number of bins by favoring tighter fits in remaining bins.
    score += (mean_residual - post_res) * progress;

    // Favor opening a new bin only if the current best fit is poor (high post_residual).
    // The new bin candidate has post_residual == (100 - item_size).
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin decreases as we approach the end of the stream
        // to ensure we don't leave too much empty space in open bins.
        score += 35.0 - (progress * 10.0);
    }

    // Penalize fragmented states where many bins are open.
    score += (open_bins_count as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
