            } else if post_residual < 10 {
                score += 20.0; // Penalize bins that will be too small for almost anything
            }
        }

        // Favor bins that maintain the mean residual to keep bin levels balanced
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.2;
    }

    // If this is the last chance to fit an item in an existing bin, prioritize it
    // strongly to avoid opening a new bin unnecessarily.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
