    // This discourages "wasting" space that could have been used by a larger item.
    if (post_residual as f64) < mean_residual * 0.5 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score: punish larger residuals to encourage Best-Fit behavior.
    let mut score = post * post;

    // Penalty for creating a bin with a residual that is "unusable" (too small for most items).
    // If post_residual is between 1 and 9, it's highly likely to be wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 500.0 * (1.0 - (post / 10.0));
    }

    // Lookahead logic: if the next item is large and the current bin can fit it,
    // we want to preserve space. If the current bin cannot fit the next item, 
    // we are more willing to accept a tighter fit now.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= (post_residual - next_item_size) as f64 * 2.0;
        } else {
            score += (next_item_size - post_residual) as f64 * 1.5;
        }
    }

    // Dynamic pressure: As the stream progresses, become more aggressive about 
    // filling bins tightly to avoid trailing fragments.
    score += (progress * 200.0) * (post / bin_capacity as f64);

    // If this is a new bin (bin_residual == bin_capacity), penalize opening it 
    // unless the current open bins are all very poor fits.
    if bin_residual == bin_capacity {
        // Penalty is proportional to the ability to fit the item in existing bins.
        // If fitting_bins_count > 0, we heavily discourage opening a new bin.
        score += 400.0 + (fitting_bins_count as f64 * 300.0);
    } else {
        // Favor bins that bring the residual closer to the mean_residual of the system,
        // promoting uniform packing density.
        score += (post - mean_residual).abs() * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Reward Best-Fit (Minimize post_residual)
    // The base score is already post_residual.

    // 2. Harmonic Class Logic: penalize "dead zones" (residuals that can't fit typical items)
    // Items are 10-80. Residuals < 10 are effectively dead space.
    if post_residual < 10 && post_residual > 0 {
        score += 50.0;
    }

    // 3. Next-Item Lookahead: If next_item_size is large, favor bins that can accommodate it.
    // If post_residual is small but next_item_size is large, this bin becomes a bottleneck.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 20.0;
        } else {
            // Reward bins that maintain enough space for the next item
            score -= 10.0;
        }
    }

    // 4. Open-Bin Management: Penalize creating a new bin unless necessary.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Only open a new bin if the current mean residual is very high (meaning current bins are mostly empty)
        // or if we have very few open bins relative to expected remaining items.
        let progress = step_index as f64 / total_items as f64;
        score += 45.0 - (mean_residual * 0.5) + (progress * 10.0);
    }

    // 5. Fitting Constraint: If this is the only bin that fits the current item, 
    // force selection by lowering the score significantly.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 100.0;
    }

    // 6. Harmonic Modulo Coupling: Penalize residuals that are poor multiples of 20
    // (targeting the 10-80 range).
    let rem = post_residual % 20;
    if rem > 15 || rem < 5 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating "dead space": small residuals that are unlikely to fit future items.
    // We target residuals in the range (0, 10), as items are >= 10.
