    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    // 5. Fragmentation avoidance:
    // Penalize placements that leave a "dead zone" (residual too small for any likely item).
    // Assuming typical item size distribution, residuals < 10 are often problematic.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // 6. Mean-reversion:
    // Favor bins that align with the global average residual to maintain uniform bin usage.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
