            score += (next_item_size as f64 - post_residual as f64) * 2.0;
        }
    }

    // 3. Global Efficiency: Balance against the mean residual to keep bins packed evenly.
    // If this bin is significantly emptier than the mean, penalize to keep it as a fallback.
    if (bin_residual as f64) > mean_residual {
        score += (bin_residual as f64 - mean_residual) * 0.5;
    }

    // 4. New Bin Thresholding: Discourage opening new bins unless the fit is extremely poor
    // or the current packing pressure is low.
    if bin_residual == bin_capacity {
        // Only open a new bin if the current number of open bins is very low,
        // or if fitting_bins_count is 0 (required).
        if fitting_bins_count > 0 {
            score += 85.0; // Heavy penalty for opening new bin unnecessarily
        } else {
            score -= 20.0; // Incentive to open new bin if no other options exist
        }
    }

    // 5. Progression Bias: As we approach the end of the stream, tighten the packing
    // requirements (favoring tighter fits to avoid leaving stranded items).
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit Penalty: Reward bins that are nearly full after placement.
    // We penalize larger post_residuals to encourage tight packing (Best Fit strategy).
    score += (post_residual as f64).powf(1.1);

    // 2. Lookahead Integration: If the next item fits into the current post_residual,
    // strongly incentivize this bin to reduce fragmentation.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 45.0 * (next_item_size as f64 / bin_capacity as f64);
    }

    // 3. New Bin Thresholding: Prevent opening new bins unless the current options
    // force a "bad" fit (creating a sliver of space that is hard to fill).
    if bin_residual == bin_capacity {
        // Base cost for opening a new bin.
        score = 65.0;
        // As we reach the end of the stream, opening a new bin is increasingly expensive.
        score += 40.0 * progress;
    } else {
        // 4. Global State Heuristic: If we have many open bins, penalize creating more
        // to encourage consolidating items into existing structures.
        score += (open_bins_count as f64).sqrt() * 5.0;

        // 5. Fragmentation Avoidance: If the post_residual is small (e.g., < 10),
        // it is often "dead space". Penalize this unless it's a perfect fit (0).
        if post_residual > 0 && post_residual < 10 {
            score += 25.0 * (1.0 - (post_residual as f64 / 10.0));
        }
    }

    // 6. Scarcity Constraint: If this is the last bin that can fit the item,
    // force its selection by lowering the score significantly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
