    if fitting_bins_count > 0 {
        score -= (fitting_bins_count as f64) * 0.5;
    }

    // 6. Mean Residual Balancing:
    // Penalize bins that deviate significantly from the mean to encourage uniform usage.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    score
}

