        }
    }

    // 6. Mean Residual Balancing: Penalize bins that deviate significantly from the 
    // mean residual to maintain uniform bin utilization across the set.
    let diff_from_mean = (post_residual as f64 - mean_residual).abs();
    score += diff_from_mean * 0.3;

