}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize small residuals (fragmentation) that are too small to fit common future items.
    // As we approach the end of the stream (progress -> 1.0), we become more aggressive
    // about filling bins tightly to avoid opening new ones.
    let fragmentation_penalty = if post < 20.0 && post > 0.0 {
        (20.0 - post) * (1.0 + progress)
    } else {
        0.0
    };

    // Reward bins that leave space for the lookahead item.
    let lookahead_penalty = if next_item_size > 0 && post < next_item_size as f64 {
        (next_item_size as f64 - post) * 1.5
    } else {
        0.0
    };

    // If this is the only bin that fits the item (fitting_bins_count == 1), 
    // heavily incentivize using it to avoid opening a new bin unnecessarily.
    let scarcity_reward = if fitting_bins_count == 1 { -50.0 } else { 0.0 };

    // Base score is the post-placement residual. 
    // We want to minimize residual space (Best Fit), but modulate it by 
    // the likelihood of filling that gap later.
    let base_score = post + (post * post / 100.0);

    base_score + fragmentation_penalty + lookahead_penalty + scarcity_reward
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: Penalize large residual space
    // We want to minimize post_residual, but prioritize tight fits (near 0)
    score += (post_residual as f64).powf(1.1);

    // 2. Harmonic Class Logic: Reward placements that leave room for specific item-size classes
    // If post_residual is a multiple of common item sizes, it's more likely to be filled later.
    let harmonic_penalty = (post_residual % 20) as f64;
    score += harmonic_penalty;

