            // Penalize placements that make it impossible to fit the next item here.
            score += 25.0;
        } else {
            // Reward placements that leave room for the next item.
            score -= 15.0;
        }
    }

    // 4. Pressure management: If many bins are open, favor filling the tightest one (Best Fit).
    // If few bins are open, favor bins that keep the mean_residual higher to maintain flexibility.
    let progression = step_index as f64 / total_items as f64;
    if open_bins_count > 5 {
        // Tighten up: prefer smaller post_residual
        score += (post_residual as f64) * 0.5;
    } else {
        // Conserve: prefer larger post_residual to keep space for future large items
        score -= (post_residual as f64) * 0.2;
    }

    // 5. Penalize bins that are "almost" full but leave awkward remainders.
    if post_residual >= 10 && post_residual < 20 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

