    // We penalize larger residuals exponentially to favor tighter packs.
    score += (post_residual as f64).powf(1.5);

    // 2. Lookahead Coupling: If next_item_size fits in the post_residual, 
    // significantly reduce the score to prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 5.0;
