    // 3. Mean Residual Balancing: Penalize bins that deviate significantly 
    // from the average fullness of existing bins to prevent "fragmentation".
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.5;

    // 4. New Bin Thresholding: Discourage opening a new bin unless the 
