        score += open_bins_count as f64 * 2.0;
    } else {
        // Reward placements that leave a residual which is a multiple of the next_item_size,
        // effectively creating a "perfect" fit for the lookahead.
        if next_item_size > 0 {
            let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
            score += diff * 0.2;
        }

        // Penalty for creating a "fragment": a small, unusable residual space.
        // We penalize residuals in the [1, 9] range as they are hard to fill.
        if post_residual > 0 && post_residual < 10 {
            score += 15.0 * (1.0 - (post_residual as f64 / 10.0));
        }
    }

    // Dynamic adjustment based on how many bins can actually fit the item.
    // If only one bin can fit the item, we are forced to use it, so we lower its score.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Soft constraint: keep residuals near the global mean to maintain bin uniformity.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: heavily penalize larger post_residuals
    // but reward configurations that leave space for the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward perfect or near-perfect fit for next item
            score -= (bin_capacity - post_residual) as f64 * 0.5;
            if post_residual == next_item_size {
                score -= 40.0;
