    // 2. Harmonic Class Logic: Prefer bins that result in residuals 
    // divisible by common item size clusters (e.g., leaving 20 or 25 space is often efficient).
    let rem = post_residual % 25;
    if rem == 0 {
        score -= 15.0;
    } else if rem > 20 {
