    // 3. Prevent fragmentation: Penalize opening new bins unless necessary.
    // If this is a new bin (bin_residual == bin_capacity)
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Only open a new bin if we are forced to or if existing bins are very fragmented
            score += 60.0 + (open_bins_count as f64 * 2.0);
        } else {
            score -= 10.0;
