    }

    // 4. Global state awareness:
    // If we are near the end of the stream, prioritize aggressive packing.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (mean_residual - post_residual as f64).abs() * 0.1;
