    let fragmentation_penalty = if post > 0.0 && post < 5.0 {
        20.0
    } else {
        0.0
    };

    let score = post + new_bin_penalty + lookahead_reward + mean_deviation + scarcity_reward + fragmentation_penalty;

    score
}

