            score -= 25.0;
        } else if post_residual < next_item_size && post_residual > 0 {
            // Penalize creating a bin that is too small for the next item
            score += 15.0;
        }
    }

    // 3. New Bin Thresholding: Discourage opening a new bin unless the existing 
    // open bins are highly suboptimal (high mean_residual).
    if bin_residual == bin_capacity {
        // Only consider a new bin if we are forced to or if existing bins are very empty
        if fitting_bins_count > 0 {
            score += 40.0 + (mean_residual * 0.5);
        } else {
            score -= 10.0;
        }
    }

    // 4. Harmonic Alignment: Favor bin residuals that are multiples of common item sizes (20, 25, 33).
    // This helps keep bins "clean" for future items.
    let harmonic_penalty = (post_residual % 20) as f64 * 0.5;
    score += harmonic_penalty;

    // 5. Progression Scaling: As we reach the end of the stream, prioritize closing bins
    // by preferring tighter fits (lower post_residual).
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

