    // Penalty for leaving "dead space" (gaps < 10 are often unusable for the given range 10-80).
    // We apply a non-linear penalty for residuals in the [1, 9] range as they are likely to be wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_res + 1.0);
    }

    // Lookahead coupling: If next_item_size is large and fits into this bin, prioritize this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 0.5;
    }

    // Dynamic adaptation: As the stream progresses, prioritize tighter packing.
    // We penalize opening new bins more heavily as total_items approaches, 
    // using a sigmoid-like interaction with progress.
    if bin_residual == bin_capacity {
        // High penalty for opening new bins, weighted by progress and mean_residual.
        // If mean_residual is low, we are already packing tightly; don't open new bins easily.
        score += (100.0 * progress) + (mean_residual * 0.5);
    } else {
        // Reward bins that keep the mean_residual high enough to accommodate future items.
        score -= (mean_residual - post_res) * 0.1;
    }

    // If this is the only bin that can fit the item, give it a significant priority boost.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: Penalize large residual space
    // We want the post_residual to be as small as possible (tight packing).

    // 2. Harmonic Class logic:
    // Identify if the post_residual is a 'dead' space that cannot accommodate common item sizes.
    // Small residuals (e.g., < 10) are often useless; heavily penalize them unless they are 0.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 3. Lookahead coupling:
    // If next_item_size can fit into this post_residual, reward this bin placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 4. New Bin Threshold:
    // Only open a new bin if the current fit is extremely poor (post_residual > 40)
    // or if the current bins are exhausted.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Strong penalty for opening a new bin if others exist
            score += 65.0 + (mean_residual * 0.5);
        } else {
            // If no other bins fit, base score is just capacity
            score = bin_capacity as f64;
        }
    }

    // 5. Global density management:
    // As the stream progresses, favor tighter packing to prevent fragmentation.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    // 6. Penalty for creating bins that are hard to fill (bins with high mean residual)
    // If this bin's post_residual is significantly worse than the current mean, penalize.
    if (post_residual as f64) > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.8;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Strategy: Minimize Best-Fit while penalizing "dead-zone" creation (gaps < 10, as min item size is 10).
    // Penalize opening new bins unless the current bin fit is significantly worse than average.

    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post_residual as f64;

    // Penalty for creating a "dead zone" (remaining space too small for any future item)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // Reward tighter packing relative to the mean residual
    if !is_new_bin {
        score += (post_residual as f64 - mean_residual).max(0.0) * 0.5;
