    if is_new_bin {
        // Only open a new bin if we have many open bins already or if fitting is forced to be inefficient
        score += (open_bins_count as f64 * 2.5);

        // If we have many fitting options, opening a new bin is usually sub-optimal
        if fitting_bins_count > 0 {
            score += 40.0 + (fitting_bins_count as f64 * 5.0);
        }
    }

    // Normalize by progress: as we approach the end, be more aggressive to finish bins
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: lower post_residual is generally better (tighter fit).
    // We normalize the penalty for leaving large gaps.
    score += (post_residual as f64).powf(1.1);

    // 2. Lookahead optimization: If the next item fits perfectly into the current post_residual,
    // we heavily incentivize this bin (Negative score).
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap_after_next = (post_residual - next_item_size) as f64;
        // Reward configurations that leave exactly 0 space after the next item.
        score -= (100.0 - gap_after_next * 5.0);
    }

    // 3. Avoid opening new bins prematurely:
    // If the bin is new (bin_residual == bin_capacity), penalize it unless no other bin can fit the item.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 250.0;
    }

    // 4. Mean Residual balancing:
    // If this bin's post_residual is significantly worse than the average, penalize it to keep
    // residuals uniform across bins (prevents "orphan" bins with tiny space).
    if (post_residual as f64) > mean_residual {
        score += (post_residual as f64 - mean_residual) * 2.0;
    }

    // 5. Critical thresholding:
    // If this is the last bin that can fit the item (fitting_bins_count == 1), 
    // prioritize it to avoid creating a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // 6. Progression scaling:
    // As we approach the end of the stream, prioritize closing bins (minimizing residuals).
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
    // Archetype: Adaptive Best-Fit with lookahead pressure and bin-opening suppression.

    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Penalty for creating "dead zones" (small residuals that are hard to fill)
    // We penalize residuals between 1 and 9 as they are harder to accommodate future items.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0 - (post_residual as f64 * 4.5);
    }

    // 2. Lookahead optimization: If next item fits in the current post_residual, prioritize this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
