    // 3. Global state: If we have many open bins, penalize opening a new one heavily.
    // If this is a new bin (bin_residual == bin_capacity), increase cost based on open_bins_count.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 12.0;
        // Early in the stream, favor keeping bins open; later, prioritize packing.
        score += (1.0 - progress) * 20.0;
    }

    // 4. Fitting Pressure: If this is the only bin that can fit the item, prioritize it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 5. Mean residual equilibrium: 
    // If the post_residual is close to the mean_residual, it indicates a balanced fill.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    // 6. Final scaling for new bin thresholding:
    // Ensure new bins are only opened if the fit in existing bins is objectively poor.
    if bin_residual == bin_capacity {
        score += 15.0; 
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize the creation of a new bin (bin_residual == bin_capacity)
    // heavily early on, but allow it if it's the only option or late in the stream.
    let new_bin_penalty = if bin_residual == bin_capacity {
        if fitting_bins_count == 0 { 0.0 } else { 50.0 * (1.0 - progress).powf(0.5) + 20.0 }
    } else { 
        0.0 
    };

    // Calculate a "tightness" score: lower post_residual is better (Best Fit).
    // We use a quadratic penalty for large residuals to prefer tight packing.
    let tightness = post.powi(2) / bin_capacity as f64;

    // Lookahead logic: if next_item_size is large, avoid leaving small residuals
    // that are too small to fit the next item.
    let lookahead_penalty = if next_item_size > 0 && post < next_item_size as f64 && post > 0.0 {
        (next_item_size as f64 - post) * 1.5
    } else {
        0.0
    };

    // Interaction with global state: penalize opening many bins if mean_residual is high.
    // This encourages filling existing bins that are already "loose".
    let fragmentation_penalty = (mean_residual - post) * (open_bins_count as f64 / 10.0);

    new_bin_penalty + tightness + lookahead_penalty + fragmentation_penalty
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: penalize large residuals (standard)
    // 2. Harmonic penalty: heavily penalize residuals that are small but non-zero (fragments)
    // If post_residual is in (0, 10), it's likely "dead space".
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 0.1);
    }

    // 3. Lookahead integration: Try to keep space for the next item
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalize bins that cannot fit the lookahead item
            score += 40.0;
        } else {
            // Reward bins that leave exactly enough or close to space for next_item_size
            let slack = (post_residual - next_item_size) as f64;
            score -= (100.0 - slack).sqrt();
        }
    }

    // 4. Harmonic class logic: Favor bins that reach specific occupancy thresholds (e.g., 100, 50, 33)
    // We reward post_residual values that are close to multiples of common item sizes
    let harmonic_fit = (post_residual % 20) as f64;
    score += harmonic_fit * 0.5;

    // 5. Global state management: discourage opening new bins unless necessary
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Only open a new bin if the average residual is already high (bins are empty)
        // or if we have very few open bins.
        if open_bins_count > 0 {
            score += 45.0 + (mean_residual * 0.5);
        }
    } else {
        // Favor packing into existing bins, especially if it's the last fitting bin
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    // 6. Progression scaling: As we approach the end of the stream, be more aggressive
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
