pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Reward Best Fit behavior (minimizing post_residual)
    // 2. Penalty for creating "orphan" space (small residuals that are unlikely to fit future items)
    // Thresholds 10, 20 are critical as item sizes start at 10.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 3. Lookahead logic: if next_item_size is known, penalize bins that cannot fit it
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 25.0;
        } else {
            // Reward bins that can accommodate the next item perfectly
            score -= (post_residual - next_item_size) as f64 * 0.5;
