    // 4. If this is the only bin that fits the current item, prioritize it to avoid new bin creation
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 5. Harmonic grouping: penalize residuals that are not multiples of common item size intervals
    // This helps keep bins "aligned" for potential future items of similar sizes
    if post_residual % 10 != 0 {
        score += 5.0;
    }

    // 6. Global pressure: if we are late in the stream, be more aggressive about filling bins
    let progress = step_index as f64 / total_items as f64;
    score += (progress * 10.0);

    // 7. Balance open bins: avoid opening new bins unless the current configuration is inefficient
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            // High penalty for opening a new bin if other bins exist
            score += 35.0 + (mean_residual * 0.2);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

