pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize the creation of "dead zones" (small remainders that are hard to fill).
    // The objective is to keep the bin as full as possible (minimizing post_residual).
    // We add a penalty for post_residual < 10, as these are often "wasted" spaces.
    let dead_zone_penalty = if post < 10.0 && post > 0.0 { 15.0 - post } else { 0.0 };

    // Non-linear coupling: As the stream progresses, prioritize tighter fits more aggressively.
    // We dampen the score if the bin is empty to provide a baseline cost for opening new bins.
    let base_score = if bin_residual == bin_capacity {
        // Cost of opening a new bin is scaled by the current mean_residual to avoid 
        // starting new bins when existing bins are already underutilized.
        45.0 + (mean_residual * 0.5) + (progress * 10.0)
    } else {
        post
    };

    // Lookahead logic: if the next item could potentially fit into this post_residual,
    // reward this bin choice to consolidate items.
    let lookahead_bonus = if next_item_size > 0 && (post_residual >= next_item_size) {
        -12.0 * (1.0 - progress)
    } else {
        0.0
    };

    // Penalize if this is the only bin that can fit the item, forcing usage of existing
    // capacity before opening new, unless the fit is extremely poor.
    let scarcity_adjustment = if fitting_bins_count == 1 && bin_residual != bin_capacity {
        -5.0
    } else {
        0.0
    };

    base_score + dead_zone_penalty + lookahead_bonus + scarcity_adjustment
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
