    // 2. Penalty for creating "orphan" bins: If this is the only bin that fits the current item, 
    //    increase its priority (lower score) to avoid opening a new bin prematurely.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
