    // Best-fit principle: favor smaller post_residual (tighter packing)
    let base_score = post_residual as f64;

    // Lookahead interaction: if next_item_size is large, penalize small post_residuals 
    // that leave no room for the next item (creating "dead space")
    let lookahead_penalty = if next_item_size > 0 && next_item_size > post_residual {
        (next_item_size - post_residual) as f64 * 1.5
    } else {
        0.0
    };

    // Coupling: If fitting_bins_count is low (e.g., 1), we are forced to be careful.
    // We reward placements that keep the bin residual close to the global mean, 
    // discouraging outlier bins that are too empty or too full.
    let mean_alignment = (post_residual as f64 - mean_residual).abs() * 0.5;

    // Final score: lower is better
    // We combine the base fit, the lookahead penalty, the new bin cost, and the mean alignment
    base_score + new_bin_penalty + lookahead_penalty + mean_alignment
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating "dead space": small residuals that are unlikely to fit future items.
    // We define "unusable" as less than the minimum observed item size threshold (10).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // Lookahead logic: if the next item can fit in the remaining space, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
