    // Harmonic preference: favor bins that leave residuals which are multiples of common item sizes (25, 33, 50).
    // This helps align bin usage with potential future item clusters.
    let harmonic_alignment = (post_residual % 25) as f64;
    score += harmonic_alignment * 0.5;

