        }
    }

    // 3. Balance against mean_residual to prevent fragmentation
    // If the post_residual is significantly lower than the global mean, it's a tight pack; reward it.
    if (post_residual as f64) < mean_residual {
        score -= 10.0 * (1.0 - (post_residual as f64 / mean_residual));
    }

    // 4. New Bin Logic:
    // If bin_residual == bin_capacity, this is a "new bin" candidate.
    // Only open a new bin if the current "best" fit is extremely poor (post_residual > 40).
    if bin_residual == bin_capacity {
        score += 45.0; // High base penalty to force filling existing bins
        if fitting_bins_count == 0 {
            score -= 100.0; // Must open if nothing else fits
        }
    }

    // 5. Progression scaling: As we approach the end of the stream, be more conservative with new bins
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

