pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Penalize creating "dead space" (small residuals that are hard to fill)
    // Residuals in the range [1, 9] are extremely difficult to fill given item sizes [10, 100].
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead logic: If the next item fits into the current post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. Dynamic Thresholding: As the stream progresses, become more conservative about opening new bins.
    // If this is a new bin (bin_residual == bin_capacity), penalize it based on how many 
    // existing bins could have taken the item.
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin if other options exist
        score += (fitting_bins_count as f64) * 40.0;
        // Late-stage penalty to discourage opening new bins near the end of the stream
        score += progress * 30.0;
    } else {
        // 4. Global State: Prefer bins that are already "tight" to keep others empty.
        // We reward bins that are closer to the mean residual of the system.
        score -= (bin_residual as f64 - mean_residual).abs() * 0.1;
    }

    // 5. Hard constraint: If this is the last chance for an item (fitting_bins_count == 1),
    // reduce the score to ensure we don't open a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize opening a new bin heavily in the early/mid stages, 
    // but allow it if the current fit leaves a very awkward "dead zone".
    let is_new_bin = bin_residual == bin_capacity;

    // Non-linear penalty for creating small, unusable residuals (the "fragmentation" penalty).
    // Small post_residuals are generally bad (1-10 range), unless they are 0.
    let fragmentation_penalty = if post == 0.0 { 0.0 } else { (1.0 / (post + 1.0)) * 20.0 };

    // Coupling the lookahead: if next_item_size is large and we don't have space, 
    // prioritize keeping the current bin open rather than starting a new one.
    let lookahead_pressure = if next_item_size > post_residual { 15.0 } else { 0.0 };

    // Base score: favor tighter fits (smaller post_residual).
    let mut score = post + fragmentation_penalty + lookahead_pressure;

    // Dynamically adjust the cost of opening a new bin based on progress.
    // As we approach the end of the stream, be more willing to open new bins to pack tightly.
    if is_new_bin {
        let new_bin_base_cost = 45.0;
        let progress_discount = progress * 15.0;
        score = new_bin_base_cost - progress_discount;
    } else {
        // If this bin is the only one that fits, give it a significant priority boost.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }

        // Penalize bins that deviate significantly from the mean residual to keep packing uniform.
        let deviation = (post - mean_residual).abs();
        score += deviation * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: prioritize smaller post_residuals (tight packing)
    // 2. Penalty for creating "dead space": if post_residual is too small to fit common small items (e.g., < 10),
    //    it might be better to leave it slightly larger or force a better fill.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0; 
    }

    // 3. Lookahead Logic: If next_item_size is large, favor bins that can accommodate it.
    // If current post_residual is smaller than next_item_size, we penalize the bin 
    // because it forces a new bin creation for the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 40.0;
        } else {
            // Reward bins that maintain enough space for the lookahead item
            score -= 15.0;
        }
    }

    // 4. Harmonic/Modulo Logic: Favor bins that leave room for perfect divisors of capacity.
    // This targets 100, 50, 25, 20, 10 increments.
    if post_residual % 25 == 0 {
        score -= 10.0;
    }

    // 5. New Bin Threshold: Discourage opening a new bin unless the current fit is extremely poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score = 65.0;

        // If we have many open bins that already fit the item, opening a new one is inefficient.
        if fitting_bins_count > 0 {
            score += (fitting_bins_count as f64) * 20.0;
        }

        // As the stream progresses, become more conservative about opening new bins.
        let progress = step_index as f64 / total_items as f64;
        score += progress * 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
