    // If post_residual is in the "danger zone" (1..9), it is almost always unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. Lookahead Synergy: If the next item fits into the current post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. Open Bins Pressure: Penalize opening a new bin if other bins are available and efficient.
    // We heavily penalize the new bin (bin_residual == bin_capacity) if fitting_bins_count > 0.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 40.0 + (open_bins_count as f64 * 2.0);
    }

    // 4. Tight Fit Reward: If the item fits almost perfectly, prioritize it.
    if post_residual == 0 {
        score -= 15.0;
    }

    // 5. Global Efficiency Balancing: Penalize bins that create a large deviation from the mean_residual.
    // This helps keep bins packed to a similar density.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    // 6. Progression Scaling: As we approach the end of the stream, prioritize closing existing bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && bin_residual == bin_capacity {
        score += 100.0; // Avoid opening new bins near the end
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

