    // (space too small for common items).
    // If post_residual is small but > 0, it is often worse than 0.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2. Lookahead matching: If the next item fits perfectly into the current post_residual,
    // give this bin a massive priority boost.
    if next_item_size > 0 && post_residual >= next_item_size {
        let diff = (post_residual - next_item_size) as f64;
        score -= (50.0 - diff).max(0.0);
    }

    // 3. New Bin Management: If this is a new bin, penalize it unless no other bin 
    // can provide a good fit or the current bins are too fragmented.
    if bin_residual == bin_capacity {
        score += 40.0;
        // If we are at the end of the stream, avoid opening new bins.
        let progress = step_index as f64 / total_items as f64;
        score += progress * 20.0;
    }

    // 4. Fragment Avoidance: If this bin's residual is significantly lower than 
    // the mean residual of open bins, we prefer to fill it to normalize fragmentation.
    if (bin_residual as f64) < mean_residual {
        score -= 10.0;
    }

    // 5. Last Chance Logic: If this is the only bin that fits the current item, 
    // heavily favor picking it to avoid forced new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // 1. Penalize creating "fragmented" bins (near-zero residuals that are too small for common items)
    // We penalize residuals in the range [1, 9] heavily as they are likely useless.
    if !is_new_bin && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead logic: If the next item fits better in this residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 * (next_item_size as f64 / bin_capacity as f64);
    }

    // 3. Dynamic Thresholding: As the stream progresses, become more conservative about opening new bins.
    if is_new_bin {
        // Higher penalty for new bins as we approach the end of the stream
        score += 15.0 + (progress * 40.0);

        // If there are other bins that could fit this, penalize opening a new one
        if fitting_bins_count > 0 {
            score += 60.0 * (1.0 - progress);
        }
    } else {
        // Reward bins that keep the global mean residual healthy
        // If post_residual is closer to the mean, it's a good "stable" fit.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.2;
    }

    // 4. Force Best-Fit decreasing behavior: Prefer tighter fits (lower post_residual)
    // but weigh against the risk of creating a bin that is too small for future use.
    score += (post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score: punish larger post_residual (Best Fit principle).
    let mut score = post;

    // Penalty for leaving small, unusable gaps (1..10) that are hard to fill later.
    // We increase score (penalize) if post_residual is in the "dead zone".
    if post_residual > 0 && post_residual < 10 {
        score += 20.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // Lookahead logic: if the next item fits into the current post_residual, 
    // prioritize this bin to prepare for a tight packing.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 15.0;
    }

    // Dynamic pressure: As the stream progresses, favor packing tighter to 
    // reduce the total number of bins opened late in the sequence.
    let tightness_factor = (1.0 - progress) * 10.0;
    score += (post / bin_capacity as f64) * tightness_factor;

    // Favor bins that are already "half-full" to keep open_bins_count low.
    let utilization = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= utilization * 5.0;

    // If this is the only bin that can fit the item, prioritize it to avoid 
    // opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New bin logic: Only open a new bin if the residual is high enough that
    // it creates a significant "waste" penalty.
    if bin_residual == bin_capacity {
        // High base cost for opening a new bin, offset by stream progress
        // to allow more flexibility at the end of the stream.
        score = 85.0 - (progress * 20.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Heuristic #1246: Harmonic-Residual Balancing
    // Strategy: Penalize small residuals (dead space) unless the next item is likely to fit.
    // Favors "tight" packing by rewarding bins that approach capacity.

    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post_residual as f64;

    if is_new_bin {
        // Penalty for opening a new bin: base cost is high (75) to force usage of existing bins.
        // Scale penalty inversely with the remaining progress to allow opening bins at the end of the stream.
        let progress = step_index as f64 / total_items as f64;
        score = 75.0 + (progress * 25.0);
    } else {
        // 1. Harmonic Penalty: Penalize residuals that are too small to fit common items (10-30).
        // If post_residual is in [1, 15], it's a "dead zone" for most medium items.
        if post_residual < 15 {
            score += 20.0;
        }

        // 2. Lookahead Coupling: If next_item_size is known, reward bins that can accommodate it.
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                // Perfect fit reward
                score -= 10.0;
            } else {
                // Penalty if we create a bin that cannot fit the next item when it could have
                score += 5.0;
            }
        }

        // 3. Density Normalization: If we have many open bins, prioritize filling the emptiest ones.
        // This spreads the load to avoid having many bins with tiny residuals.
        score += (bin_residual as f64 - mean_residual) * 0.5;

        // 4. Critical Threshold: If this is the only bin that fits, prioritize it heavily.
        if fitting_bins_count == 1 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
