    }

    // 4. Open Bins Pressure: If we have many open bins, penalize opening more 
    // and reward filling existing ones that have low residuals.
    let bin_density_pressure = (open_bins_count as f64) * 0.5;
    score += bin_density_pressure;

    // 5. Mean residual alignment: Reward bins that stay close to the mean residual
    // to keep the "level" of bin fullness consistent across the set.
    let residual_delta = (post_residual as f64 - mean_residual).abs();
    score += residual_delta * 0.1;

    // 6. Urgency: If this is the only bin that fits the item, make it highly attractive.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
