}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Heuristic Penalty: Avoid "fragile" bins.
    // If we create a post_residual that is too small for any likely item (e.g., < 10),
    // it effectively becomes dead space. Penalize residuals in the (0, 10) range.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 - (post_residual as f64 * 5.0);
    }

    // 2. Lookahead Synergy: If the next item fits perfectly into the post_residual,
    // reward this bin choice heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let diff = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 / (1.0 + diff));
    }

    // 3. Global Efficiency: Balance the current bin's residual against the global mean.
    // We prefer bins that stay closer to the mean_residual to keep distribution uniform.
    let dev_from_mean = (post_residual as f64 - mean_residual).abs();
    score += dev_from_mean * 0.2;

    // 4. New Bin Logic: If this is an empty bin, penalize it based on how many
    // fitting bins are available. We only want to open a new bin if the current
    // fitting options are poor (e.g., they create high fragmentation).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Apply a significant penalty for opening a new bin if existing ones work.
            score += 60.0 + (fitting_bins_count as f64 * 5.0);
        } else {
            // No other choice, normalize the cost of opening a new bin.
            score = 10.0;
        }
    }

    // 5. Progression weighting: As the stream nears the end, prioritize tightly packing
    // to avoid leaving items for the final bins.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
