    // The base score is already post_residual.

    // 2. Penalty for opening a new bin prematurely:
    // If bin is new, add a penalty that decreases as we approach the end of the stream.
    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 - progress);
    }

    // 3. Lookahead logic:
    // If the next item is large, penalize small post_residuals that would orphan the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.8;
        } else {
            // Reward bins that can accommodate the next item.
