            score -= 10.0;
        }
    }

    // 5. Critical threshold:
    // If this is the only bin that fits, heavily favor it to avoid wasting space elsewhere.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 6. Avoid "Dead Space" creation:
    // If post_residual is small but > 0, it's often better to fill it if it's very small (e.g. < 5).
    if post_residual > 0 && post_residual < 5 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the remaining space (Best Fit principle)
    let mut score = post_residual as f64;

    // Penalty for opening a new bin: scales with progress to force consolidation late in the stream
    if is_new_bin {
        // As the stream progresses, we want to be increasingly reluctant to open new bins
        score += (bin_capacity as f64) * (1.0 + 2.0 * progress);
    } else {
        // Heuristic: Prefer bins where the post_residual is small (tight fit)
        // We add a non-linear penalty for "wasted" space that could have fit the next item
        if next_item_size > 0 {
            if post_residual < next_item_size {
                // This bin becomes unusable for the next item, penalize proportionally
                score += (next_item_size - post_residual) as f64 * 1.5;
            }
        }

        // Coupling: If this is the last fitting bin, prioritize it to avoid opening a new one
        if fitting_bins_count == 1 {
            score -= (bin_capacity - post_residual) as f64 * 0.5;
        }

        // Interaction: Penalize deviations from the mean_residual to keep bins balanced
        let residual_diff = (post_residual as f64 - mean_residual).abs();
        score += residual_diff * 0.2;
    }

    // Dynamic scale adjustment based on stream density
    score *= 1.0 + (open_bins_count as f64 / (total_items as f64 * 0.1 + 1.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
