        }
    }

    // 4. Global state coupling: Penalize opening too many bins as the stream progresses.
    let progress = step_index as f64 / total_items as f64;
    score += (open_bins_count as f64) * progress * 5.0;

    // 5. Mean residual equilibrium: Discourage bins that deviate significantly from the mean
    // to keep the bin distribution uniform.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
