pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit Penalty: Minimize post_residual, but prioritize tight fits (Best-Fit principle).
    // Penalize large gaps quadratically.
    score += (post_residual as f64).powf(1.5);

    // 2. Lookahead Synergy: If the next item fits into the post_residual, reduce the score.
    // This encourages "pairing" items to reduce future bin openings.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 2.5;
    }

    // 3. Fragmentation Avoidance: If the remaining space is too small to be useful
    // (e.g., < 10, the minimum item size), penalize it heavily to avoid "dead space".
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 4. Global State Awareness:
    // If we have many open bins, we are incentivized to fill existing ones even if the fit is suboptimal.
    // If we have very few, we can be pickier.
    score += (open_bins_count as f64) * 0.5;

    // 5. Dynamic Thresholding:
    // As the stream progresses, increase the cost of opening new bins (bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        score += 40.0 + (progress * 30.0);
    }

    // 6. Last Chance Logic:
    // If this is the only fitting bin, lower the score to force consolidation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 7. Mean Residual Balancing:
    // Avoid bins that deviate significantly from the average residual of open bins.
    let residual_diff = (bin_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    score
