pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Penalize opening new bins heavily early on, but allow it if current bins are very full.
    // As progress approaches 1.0, we become more tolerant of opening new bins to clear out small items.
    let new_bin_penalty = if is_new_bin {
        (1.0 - progress) * 50.0 + (open_bins_count as f64 * 2.0)
    } else {
        0.0
    };

    // Calculate "tightness": we prefer residuals that are close to 0 (perfect fit).
    // post_residual^2 penalizes large gaps quadratically.
    let mut score = (post_residual * post_residual) as f64;

