    if (bin_residual as f64) > mean_residual {
        score -= 10.0;
    }

    // 6. Last Chance Logic:
    // If this is the only bin that can fit the item, prioritize it strongly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Strict Dead Space Avoidance: Penalize gaps that are too small to fit any expected future items.
    // Given the range 10-80, a residual < 10 is effectively "dead" space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead Synergy: If the next item fits into the current post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. Open Bins Pressure: Penalize opening a new bin if other bins are available.
    // If this is a new bin (bin_residual == bin_capacity) and other bins could take the item, penalize heavily.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 60.0 + (open_bins_count as f64 * 2.0);
    }

    // 4. Tightness bias: Favor bins that are already tight, but avoid bins that are nearly full 
    // unless they can exactly fit the current item (Best Fit logic).
    if post_residual == 0 {
        score -= 10.0;
    }

    // 5. Progression scaling: As the stream nears the end, become more conservative about 
    // opening new bins to avoid leaving too many under-filled bins.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base Strategy: Best Fit Decreasing logic
    // We want to minimize the post_residual (Best Fit), so lower is better.

    // 2. Lookahead Penalty:
    // If the next item is coming, we penalize bins that cannot fit it after current placement.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalize leaving a gap that is too small for the next item
            score += (next_item_size - post_residual) as f64 * 1.5;
        } else {
            // Reward creating a bin that is a "perfect" match for the next item
            let diff = (post_residual - next_item_size) as f64;
            score -= (100.0 - diff) * 0.2;
        }
    }

    // 3. New Bin Management:
    // If this is a new bin, penalize it unless we have no other choice.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if we can fit the item elsewhere
            score += 150.0;
        } else {
            // If we MUST open a new bin, normalize its score to be competitive
            score = 50.0;
        }
    }

    // 4. Global Density Optimization:
    // Prefer bins that stay closer to the mean residual of the system
    // to avoid creating "outlier" bins that are very empty or very full.
    let residual_deviation = (post_residual as f64 - mean_residual).abs();
    score += residual_deviation * 0.1;

    // 5. Progression Scaling:
    // As we approach the end of the stream, prioritize closing bins (lower residual)
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize post_residual, but heavily penalize small fragments 
    // that are unlikely to accommodate future items.

    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items as f64;

    // Base score: prioritize tighter fits
    let mut score = post_residual as f64;

    // Penalty for creating "slivers" (unusable space < 10, given item range 10-100)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // Lookahead logic: If the next item is large, favor bins that can accommodate it.
    // If post_residual is smaller than next_item, we penalize the bin.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0 * (1.0 - progress);
    }

    // Global state: discourage opening new bins unless necessary or if 
    // existing bins are highly fragmented.
    if is_new_bin {
        // Base cost for new bin
        score += 35.0;

        // If we have many bins with decent space, opening a new one is inefficient.
        if open_bins_count > 0 && mean_residual > 20.0 {
            score += 40.0;
        }
    } else {
        // Reward filling existing bins that are already "half-empty" to consolidate
        if bin_residual < (bin_capacity / 2) {
            score -= 5.0;
        }

        // If this is the only bin that fits the current item, prioritize it strongly
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    // Dynamic horizon: as we approach the end of the stream, prioritize 
    // closing bins (minimizing open_bins_count)
    score += (open_bins_count as f64) * progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the remaining space (Best Fit logic).
    let mut score = post;

    // Penalty for leaving small, unusable gaps (fragmentation).
    // If post_residual is < 10, it's likely dead space.
    if !is_new_bin && post < 10.0 {
        score += 50.0 * (1.0 - (post / 10.0));
    }

    // Lookahead coupling: If the next item fits into the current post_residual,
    // prioritize this bin to preserve bin density.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 25.0 * (1.0 - progress);
    }

    // Discourage opening new bins early in the stream, but allow it if 
    // the current fitting options are poor (high fragmentation).
    if is_new_bin {
        // Base cost of a new bin is high, but decays as the stream progresses
        // to allow for better packing density towards the end.
        score += 40.0 * (1.0 - progress);

        // If we have many open bins, penalize opening another one.
        score += open_bins_count as f64 * 2.0;
    } else {
        // Reward bins that keep the mean residual low, favoring tight packing.
        if (post as f64) < mean_residual {
            score -= 10.0 * (1.0 - progress);
        }
    }

    // If this is the only bin that can fit the item, give it a significant boost
    // to prevent unnecessary new bin creation.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: Penalize large residual space
    // We want the post_residual to be as small as possible to minimize fragmentation.
    score += post_residual as f64 * 1.5;

    // 2. Lookahead logic (next_item_size):
    // If we have a next item, try to leave enough space for it (or pack tight to finish).
    // If next_item_size fits in the post_residual, reward that bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 2.5;
    }

    // 3. Harmonic class awareness:
    // Penalize small "dead" gaps that are too small for common items (e.g., < 10).
    if post_residual < 10 && post_residual > 0 {
        score += 50.0;
    }

    // 4. Open-bin management:
    // If this is a new bin (bin_residual == bin_capacity), penalize it 
    // unless no other bins can fit the item or the remaining space is very poor.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 60.0; // Heavy penalty for opening new bins if alternatives exist
        }
    }

    // 5. Global state normalization:
    // Encourage filling bins that are already "near full" compared to the mean.
    if (bin_capacity - bin_residual) as f64 > mean_residual {
        score -= 10.0;
    }

    // 6. Progressive tightening:
    // As we approach the end of the stream, prioritize closing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score += (open_bins_count as f64) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize "Dead Space" (residual gaps that are too small to fit typical future items).
    // If post_residual is < 10 (the minimum item size), it is essentially wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 0.1);
    }

    // 2. Lookahead logic: If the next item can fit in the current post_residual,
    // reward this bin to keep the next item packed tightly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. Open Bin Pressure: Discourage opening new bins (bin_residual == bin_capacity)
    // unless the fit is truly terrible in all existing bins.
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin proportional to how many bins are already open.
        score += 40.0 + (open_bins_count as f64 * 2.0);
    } else {
        // 4. Prefer bins that are already "half-full" to keep the number of active bins low.
        // We reward bins that maintain a residual close to the current mean_residual.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.5;
    }

    // 5. Urgency: If this is the last fitting bin, prioritize it to avoid opening a new one later.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 6. Progression scaling: As we approach the end of the stream, prioritize packing
    // more aggressively by penalizing large post_residuals more heavily.
    let progress = step_index as f64 / total_items as f64;
    score += (post_residual as f64) * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
    // Archetype: Aggressive Best-Fit with 2-step lookahead and density pressure.

    let mut score = post_residual as f64;

    // 1. Penalize new bin opening (bin_residual == bin_capacity) unless forced or highly beneficial
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 150.0; // Heavy penalty for opening new bin if others can fit
        } else {
            score -= 50.0; // Natural state for first item
        }
    }

    // 2. Lookahead optimization: If current fit leaves space for the next item, prioritize it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward fits that can accommodate the next item perfectly (Best Fit approximation)
            score -= (100.0 - (post_residual as f64 - next_item_size as f64)) * 0.5;
        } else {
            // Penalize creating a bin that cannot fit the next item if it could have been avoided
            score += 20.0;
        }
    }

    // 3. Pressure management: If we have many open bins, prioritize filling the tightest one.
    // If post_residual is very small (near zero), it's an excellent packing.
    if post_residual < 5 {
        score -= 40.0;
    }

    // 4. Mean residual alignment: Avoid bins that deviate significantly from the average state
    // to keep the bin distribution uniform.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    // 5. Progression scaling: As we approach the end of the stream, prioritize closing bins
    // by favoring smaller post_residuals more aggressively.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.5);

    score
}
